@import '../../style/default.less';

@scm-select-prefix-cls: ~'@{tod-prefix}-scm-select';


.@{scm-select-prefix-cls}{
    &-tag{
        margin-right: 8px;
    }
    &-version{
        color: var(~'@{tod-cssvars-prefix}-color-text-1');
        font-weight: 500;
    }
    &-divider{
        margin: 8px;
        padding: 2px;
        border-radius: 100%;
        background-color: var(~'@{tod-cssvars-prefix}-color-text-3');
    }
    &-content{
        overflow: hidden;
        text-overflow: ellipsis;
    }
}

.@{arco-prefix}-select-option-selected{
    .@{scm-select-prefix-cls}-version{
        color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'))
    }
    .@{scm-select-prefix-cls}-divider{
        background-color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'))
    }
}
.@{arco-prefix}-select-option-disabled{
    .@{scm-select-prefix-cls}-version{
        color: var(~'@{tod-cssvars-prefix}-color-text-4');
    }
    .@{scm-select-prefix-cls}-tag{
        filter: opacity(0.5);
    }
    .@{scm-select-prefix-cls}-divider{
        color: var(~'@{tod-cssvars-prefix}-color-text-4');
    }

}

.@{scm-select-prefix-cls}-options-tab{
    margin-bottom: 8px;
}
.@{scm-select-prefix-cls}-tooltip{
    .@{arco-prefix}-tooltip-content{
        background-color: @color-bg-white;
        color: var(~'@{tod-cssvars-prefix}-color-text-2');
    }
    .@{arco-prefix}-trigger-arrow.@{arco-prefix}-tooltip-arrow{
        background-color: @color-bg-white;
        z-index: auto;
    }
}

.@{scm-select-prefix-cls}-tag.@{arco-prefix}-tag-checked.@{arco-prefix}-tag-bordered.@{arco-prefix}-tag-green{
     color: rgb(var(~'@{tod-cssvars-prefix}-green-7'));
     border-color: rgb(var(~'@{tod-cssvars-prefix}-green-2'));
     background-color: transparent;
     min-width: 66px;
     &:hover {
       border-color: rgb(var(~'@{tod-cssvars-prefix}-green-2'));
     }
}
.@{scm-select-prefix-cls}-tag.@{arco-prefix}-tag-checked.@{arco-prefix}-tag-bordered.@{arco-prefix}-tag-gold{
     color: rgb(var(~'@{tod-cssvars-prefix}-orange-5'));
     border-color: rgb(var(~'@{tod-cssvars-prefix}-orange-2'));
     background-color: transparent;
     min-width: 66px;
     &:hover {
       border-color: rgb(var(~'@{tod-cssvars-prefix}-orange-2'));
     }
}
.@{scm-select-prefix-cls}-tag.@{arco-prefix}-tag-checked.@{arco-prefix}-tag-bordered.@{arco-prefix}-tag-gray{
     color: rgb(var(~'@{tod-cssvars-prefix}-gray-7'));
     border-color: rgb(var(~'@{tod-cssvars-prefix}-gray-2'));
     background-color: transparent;
     min-width: 66px;
     &:hover {
       border-color: rgb(var(~'@{tod-cssvars-prefix}-gray-2'));
     }
}

.@{scm-select-prefix-cls}-arch-tag.@{arco-prefix}-tag-checked.@{arco-prefix}-tag-bordered.@{arco-prefix}-tag-green{
     color: rgb(var(~'@{tod-cssvars-prefix}-success-6'));
     border-color: rgba(var(~'@{tod-cssvars-prefix}-success-6'), 0.2);
     background-color: rgb(var(~'@{tod-cssvars-prefix}-success-1'));
     padding: 0 3px;
     &:hover {
       border-color: rgba(var(~'@{tod-cssvars-prefix}-success-6'), 0.2);
     }
}
.@{scm-select-prefix-cls}-arch-tag.@{arco-prefix}-tag-checked.@{arco-prefix}-tag-bordered.@{arco-prefix}-tag-cyan{
     color: rgb(var(~'@{tod-cssvars-prefix}-teal-6'));
     border-color: rgba(var(~'@{tod-cssvars-prefix}-teal-6'), 0.2);
     background-color: rgb(var(~'@{tod-cssvars-prefix}-teal-1'));
     padding: 0 3px;
     &:hover {
       border-color: rgba(var(~'@{tod-cssvars-prefix}-teal-6'), 0.2);
     }
}

.@{scm-select-prefix-cls}-more-btn.@{arco-prefix}-btn-text:not(.@{arco-prefix}-btn-disabled){
    color: var(~'@{tod-cssvars-prefix}-color-text-3');
    width: 100%;
}
