@import '../../style/base.less';
@import '../components/Panels/TreePane/index.less';
@import '../components/Panels/PsmListItem/index.less';
@import '../components/PsmTab/index.less';
@import '../components/Panels/RightSelectedList/index.less';
@import '../../../style/default.less';

.singleWrap,
.multipleWrap {
  .tod-bytetree-selector-drawer-content {
    height: 100%;
    display: flex;
    flex-direction: column;
  }

  .mutiple-content {
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
    padding-left: 8px;
  }

  .tod-bytetree-selector-drawer-alert {
    margin-left: -24px;
    margin-right: -24px;
    width: unset;
    margin-bottom: 20px;
    margin-top: -20px;
  }
}

.multipleWrap {
  .arco-drawer-inner {
    .arco-drawer-header {
      height: 56px;
      line-height: 56px;
    }

    .arco-drawer-close-icon {
      top: 22px;
      font-size: 16px;
    }
  }

  .left {
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    width: 538px;
  }

  .right {
    height: 100%;
    overflow: hidden;
    flex: 1;
    padding: 8px;
    border-left: 1px solid rgba(var(~'@{tod-cssvars-prefix}-gray-3'));
  }
}

.tagBox {
  margin-left: 10px;
  color: rgba(var(~'@{tod-cssvars-prefix}-gray-6'));
}

.@{bytetreepro}-left-wrapper {
  height: 100%;
  width: 100%;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.mutiple-content {
  padding: 0;
  height: 100%;
  width: 100%;
  min-width: 400px;
  overflow: hidden;

  .left {
    height: 100%;
  }
}

.arco-rc-tooltip-button {
  padding: 20px;
}

.no-render-children .arco-tree-node-switcher {
  visibility: hidden;
}

.arco-dropdown-menu-item {
  .mark-highlight mark {
    color: rgb(var(~'@{tod-cssvars-prefix}-gray-10'));
    background-color: yellow;
    padding: 0;
    margin: 0;
    font-weight: 500;
  }
}
