
@import '../../style/default.less';
@import './textButton.less';

.@{tod-prefix}-table {
  position: relative;
  overflow: hidden;
}

.@{tod-prefix}-table-resizer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 0;
}

.@{tod-prefix}-table-resizer-item {
  position: absolute;
  top: 0;
  left: 0;
  height: 0;
}

.@{tod-prefix}-table-resizer-line {
  position: absolute;
  width: 12px;
  height: 100px;
  top: 0;
  right: -7px;
  cursor: col-resize;
  visibility: hidden;
  opacity: 0;
  transition: opacity .1s ease;
}

.@{tod-prefix}-table-resizer-line.visible {
  visibility: visible;
}

.@{tod-prefix}-table-resizer-line.highlight {
  opacity: 1;
}

.@{tod-prefix}-table-resizer-bar {
  width: 2px;
  height: 100%;
  margin-left: 5px;
  // @primary-6
  // background-color: #1664FF;
  background-color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
}

.@{tod-prefix}-table-add-row {
  margin-top: 12px;
}

.@{tod-prefix}-table-a-button {
  margin-right: 4px;
  color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
  &-disabled {
    color: rgb(var(~'@{tod-cssvars-prefix}-gray-4'));
  }
}

.@{tod-prefix}-table {
  // & &-editor {
  //   width: auto;
  // }
  &-editable-row:hover {
    .@{tod-prefix}-table-editable-cell {
      padding: 5px 11px;
      // @color-border-3
      border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-3');
      border-radius: 4px;
    }
  }
  &-editable-cell {
    box-sizing: border-box;
    padding: 6px 12px;
    min-height: 32px;
  }
}

