// @import '~styles/vars.scss';
@import '../../../../../style/default.less';

.item-wrap {
  // margin-bottom: 2px;
  flex: 1 1 auto;
  overflow-x: hidden;
  // background-color: var(~'@{tod-cssvars-prefix}-color-bg-2');
  align-items: center;

  &:hover,
  &.active {
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-2');
  }

  cursor: default;
  padding: 4px 8px;
  transition: 300ms;
  display: flex;

  .content {
    flex: 1;
    // @include text-overflow;
    // font-size: @font-size-body-2;

    .name {
      line-height: 18px;
      margin-bottom: 4px;
      word-break: break-all;
      // @include text-overflow;
    }

    .parent-path {
      font-size: 12px;
      line-height: 14px;
      color: rgb(var(~'@{tod-cssvars-prefix}-gray-6'));
      // @include text-overflow;
    }
  }

  .extra {
    color: var(~'@{tod-cssvars-prefix}-color-text-2');
  }
}

.wrap {
  max-height: 100%;
  display: flex;
  flex-direction: column;

  .header {
    flex-shrink: 0;
    font-weight: 500;
    line-height: 20px;
    padding: 4px 12px 4px 8px;

    .@{tod-prefix}-bytetree-selector-drawer-action-btn {
      color: var(~'@{tod-cssvars-prefix}-color-text-2');
      height: 24px;
      width: 24px;
      flex-shrink: 0;
    }
  }

  .content {
    margin-top: 8px;
    overflow-y: auto;
  }
}
