@import '../../style/default.less';
@import '../BaseAvatar/style/index.less';

.@{tod-prefix}-avatar-department {
  .@{arco-prefix}-avatar-text {
    height: 100%;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
}

.@{tod-prefix}-avatar-user .@{arco-prefix}-avatar-image {
  line-height: initial !important;
}

.@{tod-prefix}-avatar-tooltip-username {
  color: var(~'@{tod-cssvars-prefix}-color-text-4');
}

.@{tod-prefix}-avatar-tooltip-node.@{tod-prefix}-avatar {
  display: inline-flex;
}

.@{tod-prefix}-avatar-tooltip-spin {
  display: inline;
  .@{arco-prefix}-spin-children {
    &::after {
      background-color: transparent;
    }
  }
}

.@{tod-prefix}-avatar-tooltip-content {
  display: flex;
  width: auto;
  //max-width: 300px;
  transition: all 1000ms ease-out;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;

  &.loading {
    max-width: 50px;
  }
}

.@{arco-prefix}-popover {
  .@{tod-prefix}-avatar-department {
    border: none;
    padding: 0;
  }
}

.@{tod-prefix}-avatar-department.no-border {
  border: none;
  padding: 0;
}

.@{tod-prefix}-avatar-username {
  color: var(~'@{tod-cssvars-prefix}-color-text-2');
}
.@{tod-prefix}-avatar-user-lark {
  cursor: pointer;
  .@{tod-prefix}-overflow-text {
    cursor: pointer;
  }
  &:hover {
    .@{tod-prefix}-overflow-text,
    .@{tod-prefix}-avatar-username {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    }
  }
}

.ve-o-avatar-group.only-one {
  .@{tod-prefix}-overflow-text {
    //overflow: initial;
  }
}

.@{arco-prefix}-avatar-group.@{tod-prefix}-avatar-group {
  position: relative;
  z-index: 0;
  line-height: initial;

  .@{arco-prefix}-avatar-group-max-count-avatar {
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
    color: var(~'@{tod-cssvars-prefix}-color-text-2');
    background: #fff;
    font-weight: 500;
    border-radius: 20px;
  }
}

.@{tod-prefix}-avatar-popover .@{arco-prefix}-avatar-group-popover {
  display: flex;
  flex-direction: column;
}

.ve-o-avatar-group-popover
  .@{arco-prefix}-avatar-group-popover
  > .@{tod-prefix}-avatar-department {
  margin-bottom: 6px;

  &:last-child {
    margin-bottom: 0;
  }
}

.ve-o-avatar-group-popover
  .@{arco-prefix}-avatar-group-popover
  > .@{tod-prefix}-avatar-user {
  margin-bottom: 6px;

  &:last-child {
    margin-bottom: 0;
  }
}

.@{tod-prefix}-avatar-popover {
  .@{arco-prefix}-popover-content {
    color: var(~'@{tod-cssvars-prefix}-color-text-1');
    overflow: auto;
    padding: 8px 16px;

    .ve-o-avatar:last-child {
      margin-bottom: 0;
    }
  }

  &.mini {
    .@{arco-prefix}-popover-content {
      font-size: 12px;
      max-height: calc((20px * 5 + 16px));
    }
  }

  &.small {
    .@{arco-prefix}-popover-content {
      font-size: 13px;
      max-height: calc((24px * 5 + 16px));
    }
  }

  &.default {
    .@{arco-prefix}-popover-content {
      font-size: 13px;
      max-height: calc((28px * 5 + 16px));
    }
  }

  &.large {
    .@{arco-prefix}-popover-content {
      font-size: 16px;
      max-height: calc((44px * 5 + 16px));
    }
  }
}

.@{tod-prefix}-avatar-border {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px 1px 1px;
  border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
  border-radius: 30px;
  background-color: var(~'@{tod-cssvars-prefix}-color-bg-2');
}

.@{tod-prefix}-avatar-user-lark-tenant-tag{
  margin-left: 5px;
}
