@import '../../style/default.less';

@ve-o-prefix: @tod-prefix;

// @prefix: ve-o-empty;
@color-title: #1d2129;
@color-description: #80838a;

.@{ve-o-prefix}-empty {
  width: 100%;
  box-sizing: border-box;
  text-align: center;

  &-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 80px;
    font-size: 80px;
  }

  &-title {
    margin-top: 12px;
    font-weight: 500;
    font-size: 16px;
    line-height: 24px;
    color: @color-title;
  }

  &-description {
    margin-top: 12px;
    font-size: 13px;
    line-height: 22px;
    color: @color-description;

    .arco-volc3-link,
    .arco-link {
      padding: 1px 8px;
    }

    &--hasTitle {
      margin-top: 4px;
    }
  }

  &-action {
    margin-top: 24px;
  }

  &-space {
    display: inline-flex;
    margin-right: 12px;

    &:last-child {
      margin-right: 0;
    }
  }

  &--small {
    .@{prefix}-icon {
      height: 60px;
      font-size: 60px;
    }
    .force-icon {
      height: 60px;
      font-size: 60px;
    }
  }

  &--mini {
    .@{prefix}-icon {
      height: 48px;
      font-size: 48px;
    }
    .force-icon {
      height: 48px;
      font-size: 48px;
    }
  }
}
