@import '../../../style/default.less';
@import './token.less';

@tagProColors: blue, green, red, purple, darkGreen, gray, roseRed, darkYellow;

.status (@status) {
  &-type-@{status} {
    background-color: ~'@{tag-color-@{status}_bg}';
    color: ~'@{tag-color-@{status}}';

    .@{arco-prefix}-tag-icon,
    .@{arco-prefix}-volc3-tag-icon {
      color: ~'@{tag-color-@{status}}';
    }

    .@{vod-prefix}-tag-icon-point {
      background: ~'@{tag-color-@{status}}';
    }

    &.@{vod-prefix}-tag-all.@{vod-prefix}-tag-isDropdown {
      border: @tag-outline-border;
    }

    &.@{vod-prefix}-tag--disabled {
      color: ~'@{tag-color-@{status}--disabled}';

      .@{vod-prefix}-tag-icon-point {
        background: ~'@{tag-color-@{status}--disabled}';
      }
    }
  }

  body[arco-theme='dark'] &-type-@{status} {
    background-color: ~'@{tag-color-@{status}-dark_bg}';
  }

  &&-all {
    color: @tag-default-color;
  }
}

.@{vod-prefix}-tag-pro--disabled {
  cursor: not-allowed;
}

.@{vod-prefix}-tag-pro.@{vod-prefix}-tag-pro-big {
  display: inline-flex;
  align-items: center;

  .@{vod-prefix}-tag {
    height: @tag-default-height;
    padding: 0 6px;
    line-height: @tag-default-height;
    color: @tag-default-color;
    font-weight: 500;
    font-size: 12px;
    background: @tag-default-bg;
    border-radius: @tag-default-radius;

    .@{arco-prefix}-tag-icon,
    .@{arco-prefix}-volc3-tag-icon {
      svg {
        font-size: 14px;
        vertical-align: -1px;
      }
    }

    &-size-small {
      font-size: 10px;
      height: 16px;
      line-height: 16px;

      .@{arco-prefix}-tag-icon,
      .@{arco-prefix}-volc3-tag-icon {
        svg {
          font-size: 12px;
          vertical-align: -1.5px;
        }
      }
    }

    &-size-medium {
      font-size: 10px;
      height: 18px;
      line-height: 18px;

      .@{arco-prefix}-tag-icon,
      .@{arco-prefix}-volc3-tag-icon {
        svg {
          font-size: 12px;
        }
      }
    }

    &-size-mini {
      font-size: 10px;
      height: 16px;
      line-height: 16px;

      .@{arco-prefix}-tag-icon,
      .@{arco-prefix}-volc3-tag-icon {
        svg {
          vertical-align: -1px;
        }
      }
    }

    &-size-large {
      font-size: 13px;
      height: 24px;
      line-height: 24px;

      .@{arco-prefix}-tag-icon,
      .@{arco-prefix}-volc3-tag-icon {
        svg {
          font-size: 16px;
          vertical-align: -1px;
        }
      }
    }

    .@{arco-prefix}-tag-icon,
    .@{arco-prefix}-volc3-tag-icon {
      display: flex;
      align-items: center;
      color: @tag-default-color;

      .@{arco-prefix}-icon,
      .@{arco-prefix}-volc3-icon {
        align-items: center;
      }
    }

    .status(success);
    .status(warning);
    .status(error);
    .status(stop);
    .status(loading);
    .status(spin);
    .status(processing);

    &-outline {
      background: @tag-outline-bg;
      border: @tag-outline-border;
    }

    &-all {
      color: .colorFix(color-text-2) [ @res];
      background: @tag-all-bg;
      border: @tag-all-border;
    }

    &-text {
      background: transparent;
      box-shadow: none;
    }

    &-dashed {
      border: @tag-outline-border;
      border-style: dashed;
    }

    &-isDropdown {
      cursor: pointer;
    }

    &-dropdown {
      margin-left: 4px;
    }

    &.@{arco-prefix}-dropdown-popup-visible .@{arco-prefix}-icon-down,
    &.@{arco-prefix}-volc3-dropdown-popup-visible .@{arco-prefix}-volc3-icon-down {
      transform: rotate(180deg);
    }

    &-shape-round {
      border-radius: 20px;

      .@{vod-prefix}-tag-avatar {
        border-radius: 50%;
      }
    }

    &-icon-point {
      display: inline-block;
      width: 4px;
      height: 4px;
      margin-right: 2px;
      background: #80838a;
      border-radius: 1px;
    }

    &-avatar {
      width: 16px;
      height: 16px;
      margin-right: 4px;
      overflow: hidden;
    }

    &-avatar-img {
      display: block;
      width: 100%;
      height: 100%;
      object-fit: cover;
    }

    &-has-avatar {
      padding-left: 2px;

      .@{arco-prefix}-volc3-tag-content,
      .@{arco-prefix}-tag-content {
        display: flex;
        align-items: center;
      }
    }

    &-color {
      color: #fff;
    }

    &-label-wrap {
      display: inline-flex;
      padding: 0 8px 0 0;
      box-sizing: border-box;
      background: @tag-label-wrap-bg;
      border: @tag-outline-border;
      border-radius: 4px;
      overflow: hidden;
    }

    &-label {
      display: inline-flex;
      height: 100%;
      padding: 0 8px;
      margin-right: 8px;
      font-size: 12px;
      color: @tag-default-color;
      font-weight: 500;
      background: @tag-all-bg;
      border-right: 1px solid rgba(0, 0, 0, 0.05);
    }

    &-mark {
      display: inline-flex;
      justify-content: center;
      align-items: center;
      min-width: 20px;
      padding: 0;
      height: 18px;
      line-height: 18px;
      font-weight: 500;
      font-size: 12px;
      color: #fff;
      text-align: center;
      border: 0.5px solid transparent;
      border-radius: 8px 4px 8px 0;
      background-clip: padding-box, border-box;
      background-origin: padding-box, border-box;
      background-image: linear-gradient(90deg, #ff9878 0%, #fa2967 100%),
        linear-gradient(90deg, #ffeede 0%, #ffbeb5 50%, #ffeede 100%);
      box-sizing: border-box;
      position: relative;

      &-text {
        font-size: 12px;
        transform: scale(0.83);
        -webkit-transform: scale(0.83);
        white-space: nowrap;
      }

      &.@{vod-prefix}-tag-them-gray {
        background-image: linear-gradient(79.48deg, #9ea4c6 7.83%, #6273ab 95.76%),
          linear-gradient(90deg, #e9edfe 0%, #9ba7d2 50%, #e9edfe 100%);
      }
    }

    each(@tagProColors, {
      &-them-@{value} {
        background-color: ~'rgba(@{tag-color-@{value}}, 1)';
        background-image: none;
        &.@{vod-prefix}-tag-all {
          color: ~'rgba(@{tag-color-@{value}}, 1)';
          border: 1px solid ~'rgba(@{tag-color-@{value}}, 0.2)';
          background-color: ~'rgba(@{tag-color-@{value}}, 0.2)';
          box-shadow: none;
        }

        &.@{vod-prefix}-tag-outline {
          color: ~'rgba(@{tag-color-@{value}}, 1)';
          border: 1px solid ~'rgba(@{tag-color-@{value}}, 0.2)';
          background-color: @tag-white-bg;
          box-shadow: none;
        }
      }
    });
    &-them-gold {
      // 金标特殊处理
      border: none;
      color: #733e0f;
      background: linear-gradient(90deg, #fef5c4, #f0c573);
    }
    &-bold {
      font-weight: 700;
    }

    &--disabled {
      color: @tag-color--disabled;
      pointer-events: none;

      .@{arco-prefix}-tag-icon,
      .@{arco-prefix}-volc3-tag-icon {
        svg {
          opacity: 0.4;
        }
      }

      .@{vod-prefix}-tag-icon-point {
        background: @tag-color--disabled;
      }

      .@{vod-prefix}-tag-dropdown {
        color: @tag-color-close-disabled;
      }

      .@{arco-prefix}-tag-close-btn,
      .@{arco-prefix}-volc3-tag-close-btn {
        color: @tag-color-close-disabled !important;
        pointer-events: none;
      }
    }
  }
}
