@import '../../style/default.less';

@ve-o-prefix: @tod-prefix;

.@{ve-o-prefix}-dropdown-menu.@{arco-prefix}-dropdown-menu {
  padding: 8px 6px;
  .@{arco-prefix}-input-group-wrapper {
    margin-bottom: 4px;
    padding-left: 3px;
    padding-right: 3px;
    .@{arco-prefix}-input {
      padding-left: 4px;
      font-size: 12px;
      height: 24px;
      line-height: 24px;
    }
  }
  .@{arco-prefix}-dropdown-menu-inner {
    padding: 0;
  }
  .@{arco-prefix}-dropdown-menu-item {
    margin-top: 4px;
    margin-bottom: 4px;
    &:last-child {
      margin-bottom: 0;
    }
  }
}
