@import '../../style/default.less';

@ve-o-prefix: @tod-prefix;

.@{ve-o-prefix}-column-filter-table {
  &-popover-wrap {
    margin-bottom: 16px;
  }
  &-popover {
    .@{arco-prefix}-popover-content {
      padding: 0;
      .@{arco-prefix}-checkbox {
        white-space: nowrap;
      }
      .@{arco-prefix}-btn {
        width: 100%;
      }
    }
    .@{ve-o-prefix}-check-group-wrap {
      padding: 4px 20px 0 20px;
    }
  }
  &-divider {
    margin: 10px 0 0 0;
  }
}
