@import '../../style/default.less';

.@{tod-prefix}-overflow-text {
  word-break: break-all;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: default;
}

.@{tod-prefix}-overflow-text-mid {
  word-break: break-all;
  white-space: nowrap;
  overflow-wrap: normal;
  cursor: default;
}
