@import '../../style/default.less';

@codeBlockPrefix: ~'@{tod-prefix}-codeBlock';

.@{codeBlockPrefix} {
  display: inline-block;
  background: var(~'@{tod-cssvars-prefix}-color-bg-4');
  box-shadow: 0 1px 1px rgba(0, 0, 0, 0.05), 0 0 0 1px rgba(213, 219, 227, 0.5);
  border-radius: 4px;

  &--default {
    .@{codeBlockPrefix}-content {
      padding: 12px 16px;
    }
  }

  &--simple {
    .@{codeBlockPrefix}-content {
      padding: 0;
    }
    &.@{codeBlockPrefix}--small {
      padding: 1px 6px;

      .@{codeBlockPrefix}-content--operation {
        font-size: 12px;
      }
    }

    &.@{codeBlockPrefix}--default {
      padding: 7px 16px;
    }
  }

  .@{codeBlockPrefix}-content--operation {
    margin-left: 6px;
  }

  &-title {
    display: flex;
    align-items: center;
    height: 32px;
    padding: 0 12px;
    font-size: 12px;
    color: #1d2129;
    border-bottom: 1px solid #e6eaf0;

    .arco-select {
      width: auto;
    }

    .arco-select-arrow-icon {
      font-size: 12px;
      margin-left: 10px;
    }

    .arco-select-size-default.arco-select-single .arco-select-view,
    .arco-tabs-header-nav-text .arco-tabs-header-title {
      font-size: 12px;
      font-weight: normal;
    }

    .arco-tabs-header-nav-text .arco-tabs-header-title:last-child {
      margin-right: 0;
    }

    .arco-select {
      margin-left: -11px;
    }

    &-left {
      flex: 1;
    }
  }

  &-tooltip {
    display: inline-flex;
    justify-content: center;
    line-height: 16px;

    &__icon {
      font-size: 16px;
      margin-right: 8px;
    }
  }

  &-content {
    display: flex;
    line-height: 18px;
    color: #4e5969;
    font-size: 12px;
    word-break: break-all;

    &-code {
      padding-right: 10px;
      overflow-y: auto;
    }

    &--operation {
      font-size: 14px;
      cursor: pointer;
      color: #41464f;
    }
  }

  &-line {
    display: flex;

    &-index {
      margin-right: 24px;
      white-space: nowrap;
    }
  }
}
