@import './variables.less';

.ellipsis-on-overflow(@lines: 1) {
  display: -webkit-box;
  -webkit-line-clamp: @lines;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.scroll-bar {
  // 组件内部内置滚动条的样式
  ::-webkit-scrollbar-thumb {
    border-radius: 10px;
    transition: all 1s;
    // background-color: rgba(@N900-raw, 30%);
    border: 2px solid transparent;
    background-clip: padding-box;
  }

  ::-webkit-scrollbar {
    width: 11px;
    height: 11px;
  }

  ::-webkit-scrollbar-thumb:hover {
    // background-color: rgba(@N900-raw, 60%) !important;
  }

  ::-webkit-scrollbar:hover {
    width: 11px;
    height: 11px;
  }

  // 滚动条样式设置兼容 Firefox 浏览器，但是这些样式只能处理常态的滚动条、hover 到滚动条上了样式变成了默认样式
  scrollbar-width: 11px; // 同样的 Firefox 版本，在 mac 上生效，在 win 上是无效属性
  // scrollbar-color: rgba(@N900-raw, 30%) transparent; // 分别是滚动条 thumb 和 track 的颜色

  // 更多滚动条兼容性研究详见： https://bytedance.feishu.cn/docx/doxcn6FkXKCSM7TzP8NYVNuc7Fg#doxcn6aYKOQmemSycoft0hUgkQh
}

.shrink-transition() {
  transition: all 5s ease-out;
}
