@import '../../style/default.less';

.@{tod-prefix}-conditions-body,
.@{tod-prefix}-conditions-group-body {
  display: flex;

  .arco-btn {
    padding: 0;
  }
}

.@{tod-prefix}-conditions-content,
.@{tod-prefix}-conditions-group-content {
  flex: auto;
  position: relative;
}

.@{tod-prefix}-conditions-group-content.view {
  position: relative;
  & > div:only-child {
    position: absolute;
    top: 50%;
    transform: translate(0, -50%);
  }
}

.@{tod-prefix}-conditions-relation {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-right: 12px;

  &-upper-line,
  &-lower-line {
    flex: auto;
    border: 1px solid #EAEDF1;
    border-right: none;
    // min-height: 12px;
    width: 12px;
    margin-left: 12px
  }
  &-upper-line {
    border-radius: 4px 0;
    border-bottom: none;
    margin-top: 1em;
  }
  &-lower-line {
    border-radius: 0 0 0 4px;
    border-top: none;
    margin-top: 4px;
    margin-bottom: 1em;
    &.view {
      margin-top: 0;
    }
  }

  .@{tod-prefix}-conditions-body > & > &-upper-line.view {
    margin-top: 2em;
  }
  .@{tod-prefix}-conditions-body > & > &-lower-line.view {
    margin-bottom: 1.5em;
  }

  &-select {
    width: 80px;
  }

  &-toggle {
    position: relative;
    cursor: pointer;
  }

  &-card {
    display: inline-block;
    width: 28px;
    height: 24px;
    border: 1px solid;
    border-radius: 2px;
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-white');
    text-align: center;
    color: var(~'@{tod-cssvars-prefix}-color-text-3');
    font-size: 12px;
    line-height: 24px;
    user-select: none;
    transition: top 0.2s ease, left 0.2s ease;

    &.small {
      width: 24px;
      height: 20px;
      line-height: 20px;
      font-size: 10px;
    }

    &.first {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    }
    &.second {
      z-index: -1;
      color: rgb(var(~'@{tod-cssvars-prefix}-success-6'));
      position: absolute;
      left: -4px;
      top: 4px;
    }
  }

  &-toggle.flipped &-card {
    &.first {
      position: absolute;
      left: -4px;
      top: 4px;
    }
    &.second {
      z-index: 1;
      position: relative;
      left: 0;
      top: 0;
    }
  }
}

.@{tod-prefix}-conditions-group-content {
  .@{tod-prefix}-conditions-group-clear {
    position: absolute;
    right: 1em;
  }
}

.@{tod-prefix}-conditions-group-wrapper {
  & > .@{tod-prefix}-conditions-group-delete {
    position: absolute;
    right: .5em;
    margin-top: -2.5em;
  }
}
