@import '../../style/default.less';

@x-card-prefix: ~'@{tod-prefix}-card';


.card-status(@status) {
  &-@{status} {
    background-color: ~'var(@{tod-cssvars-prefix}-color-@{status}-light-1)';
  }
}

.@{x-card-prefix} {
  // border-color: transparent;
  padding: 16px 20px;
  position: relative;
  box-sizing: border-box;

  &-size-small {
    border-radius: var(~'@{tod-cssvars-prefix}-border-radius-medium');
  }

  &-size-default {
    border-radius: var(~'@{tod-cssvars-prefix}-border-radius-large');
  }

  &:hover {
    box-shadow: 0px 10px 20px rgba(0, 0, 0, 0.05)
  }

  &-border { // 白色描边
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
  }

  &-box-shadow {
    box-shadow: 0px 1px 2px rgba(0, 0, 0, 0.1);
  }

  &-white {
    // background-color: var(--color-bg-1);
  }

  // color
  &-gray {
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-4');
    // box-shadow: var(--color-border-2) ;
  }

  &-warning {
    background-color: var(~'@{tod-cssvars-prefix}-color-warning-light-1');
  }

  &-error {
    background-color: var(~'@{tod-cssvars-prefix}-color-danger-light-1');
  }

  &-info {
    background-color: var(~'@{tod-cssvars-prefix}-color-primary-light-1');
  }

  &-success {
    background-color: var(~'@{tod-cssvars-prefix}-color-success-light-1');
  }
}


// checkable card
.@{x-card-prefix} {
  &-checkable {
    cursor: pointer;
  }

  &-checked {
    background-color: var(--color-primary-light-1);
    border: 1px solid rgb(var(--primary-6));
  }

  &-checkable:hover &-checkbox,
  &-checked &-checkbox {
    opacity: 1;
  }

  // 禁用状态
  &-disabled,
  &-disabled:hover {
    cursor: not-allowed;
    box-shadow: unset;

    .@{x-card-prefix}-checkbox {
      opacity: 0;
    }
  }

  &-disabled&-checked,
  &-disabled&-checked:hover {
    cursor: not-allowed;
    background-color: unset;
    border-color: var(--color-border-2);

    .@{x-card-prefix}-checkbox {
      opacity: 1;
      background: linear-gradient(45deg, transparent 50%, var(--color-primary-light-3) 50%);
    }
  }

  &-checkbox {
    opacity: 0;
    width: 30px;
    height: 30px;
    position: absolute;
    right: -1px;
    top: -1px;
    font-size: 16px;
    text-align: right;
    color: var(--color-white);
    background: linear-gradient(45deg, transparent 50%, var(--color-fill-1) 50%);
    border-top-right-radius: inherit;

    &&-checked {
      background: linear-gradient(45deg, transparent 50%, rgba(var(--primary-6)) 50%);
    }

    &-icon {
      display: inline-flex;
    }
  }
}


.@{x-card-prefix}-grid {
  display: grid;
  grid-gap: 20px 20px;
}


@media screen  and (max-width: 1440px) {
  .@{x-card-prefix}-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media screen and (min-width: 1440px) and (max-width: 1680px) {
  .@{x-card-prefix}-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media screen and (min-width: 1680px) and (max-width: 1920px) {
  .@{x-card-prefix}-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

@media screen and (min-width: 1920px) {
  .@{x-card-prefix}-grid {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}


