@import '../../style/default.less';

@ve-o-prefix: @tod-prefix;

.colorFix(@var) {
  @res: var(~'--arco-volc3-@{var}', var(~'--@{var}'));
}

@text-color: .colorFix(color-text-1) [ @res];
@text-size: 13px;
@text-line-height: 20px;
@btn-size: 16px;
@btn-height: 24px;
@btn-color: .colorFix(color-fill-3) [ @res];
@btn-bg__hover: .colorFix(color-border-2) [ @res];
@icon-check-color: rgba(.colorFix(success-6) [ @res]);
@icon-close-color: rgba(.colorFix(danger-6) [ @res]);

.@{ve-o-prefix}-editableText {
  display: inline-block;
  width: 100%;

  &-title {
    display: flex;
    align-items: center;
    height: 28px;

    &__text {
      font-family: 'PingFang SC';
      font-style: normal;
      font-size: @text-size;
      line-height: @text-line-height;
      color: @text-color;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    &__btn {
      display: flex;
      align-items: center;
      justify-content: center;
      margin-left: 4px;
      padding: 4px;
      width: @btn-height;
      height: @btn-height;
      line-height: @btn-height;
      font-size: @btn-size;
      color: @btn-color;
      border-radius: 4px;
      text-align: center;
      box-sizing: border-box;
      cursor: pointer;

      &:hover {
        background: @btn-bg__hover;
      }
    }
  }

  &-Popconfirm {
    &__title {
      font-weight: 600;
      font-size: 12px;
      line-height: 20px;
      color: @text-color;
      margin-bottom: 8px;
    }
  }

  &-edit {
    display: flex;
    align-items: center;

    &-icon {
      font-size: 16px;
      margin-right: 12px;
      cursor: pointer;

      &-check {
        color: @icon-check-color;
      }

      &-close {
        color: @icon-close-color;
      }
    }
  }

  &-icons {
    margin-left: 16px;
    white-space: nowrap;
  }
}
