@import '../../style/default.less';

@action-group-prefix-cls: ~'@{tod-prefix}-action-group';

.@{action-group-prefix-cls} {
  display: inline-flex;

  &-space {
    display: inline-flex;
    align-items: center;
    margin-right: 12px;

    &:last-child {
      margin-right: 0;
    }
  }

  &--small,
  &--mini {
    .@{action-group-prefix-cls}-space {
      margin-right: 8px;

      &:last-child {
        margin-right: 0;
      }
    }
  }
}
