// @import '~styles/vars.scss';
@import '../../../../../style/default.less';

.psm_list_item-wrap {
  margin-bottom: 2px;
  flex: 1 1 auto;
  overflow-x: hidden;

  &:hover,
  &.active {
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-5');
  }

  cursor: pointer;
  padding: 4px 8px;
  transition: 300ms;
  background-color: var(~'@{tod-cssvars-prefix}-color-bg-2');
  display: flex;

  .content {
    flex: 1;
    // @include text-overflow;
    cursor: pointer;
    width: 80%;

    .name {
      line-height: 20px;
      margin-bottom: 4px;
      word-wrap: break-word;
      // @include text-overflow;
    }

    .parent-path {
      font-size: 12px;
      line-height: 18px;
      color: rgb(var(~'@{tod-cssvars-prefix}-gray-6'));
      word-wrap: break-word;
      // @include text-overflow;
    }
  }

  .extra {
    flex: 0 0 18px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    margin-right: 20px;

    // 这个类暂时没有使用到
    .recent {
      font-family: Nunito Sans, sans-serif;
      font-size: 12px;
      font-weight: 600;
      color: rgba(var(~'@{tod-cssvars-prefix}-primary-6'));
      // @include text-overflow;
      margin-right: 20px;
    }

    .heart {
      margin-top: -2px;
    }
  }
}
