@import '../../style/default.less';

@i18n-input-prefix-cls: ~'@{tod-prefix}-i18n-input';
@i18n-input-box-border: #dde2e9;
@i18n-input-box-border--hover: #4281ff;
@i18n-input-box-border--focus: #0055ff;
@i18n-input-wrapper-border-top: #d4dbe2;

.@{i18n-input-prefix-cls} {
  box-sizing: border-box;

  &--disabled {
    cursor: not-allowed;

    .@{i18n-input-prefix-cls}-box {
      pointer-events: none;
      background-color: #f6f8fa;
      border-color: #eaedf1;
      color: #80838a;
      -webkit-text-fill-color: #80838a;
    }

    &-del {
      color: #80838a !important;
    }
  }

  &-box {
    border-radius: 4px;
    padding: 0 12px;
    border: 1px solid @i18n-input-box-border;
    transition: border-color 0.1s cubic-bezier(0, 0, 1, 1);

    &:hover {
      border-color: @i18n-input-box-border--hover;
    }

    &--focus {
      box-shadow: 0 0 0 2px rgb(22 100 255 / 30%);
      border-color: @i18n-input-box-border--focus;
    }

    &--error {
      border-color: #fa9ea3;
      background-color: #feeced;

      &:hover {
        border-color: #db373f;
      }

      &.@{tod-prefix}-i18n-input-box--focus {
        box-shadow: 0 0 0 2px rgb(219 55 63 / 30%);
        border-color: #c43138;
        background: #fff;
      }
    }

    .arco-volc3-input,
    .@{arco-prefix}-input {
      line-height: 22px;
      padding-top: 6px;
      padding-bottom: 6px;
      padding-left: 10px;
    }

    .arco-volc3-textarea,
    .@{arco-prefix}-textarea {
      padding-top: 3px;
      padding-bottom: 3px;
      padding-left: 4px;
      line-height: 22px;
      resize: none;
    }

    .@{arco-prefix}-input-inner-wrapper .@{arco-prefix}-input,
    .arco-volc3-input-inner-wrapper .arco-volc3-input {
      padding-left: 0;
    }

    .@{arco-prefix}-textarea-clear-wrapper .@{arco-prefix}-textarea,
    .arco-volc3-textarea-clear-wrapper .arco-volc3-textarea {
      padding-right: 22px;
    }

    .arco-volc3-input-inner-wrapper,
    .@{arco-prefix}-input-inner-wrapper,
    .arco-volc3-input,
    .arco-volc3-textarea,
    .@{arco-prefix}-input,
    .@{arco-prefix}-textarea {
      padding-right: 0;
      background: none;
      border: none !important;
      border-radius: 0;
      background-color: transparent !important;

      &:focus {
        box-shadow: none;
        border-color: transparent;
      }

      &:hover {
        border-color: transparent;
        background: transparent;
      }
    }

    .@{arco-prefix}-input-inner-wrapper-focus,
    .arco-volc3-input-inner-wrapper-focus {
      box-shadow: none !important;
    }

    &--noRequired {
      .@{i18n-input-prefix-cls}-tag {
        width: 24px;
      }
    }
  }

  &-inputArea {
    flex: 1;
    display: inline-flex;
    align-items: center;
  }

  &-wrapper {
    display: flex;

    &:nth-child(2n) {
      border-top: 1px dashed @i18n-input-wrapper-border-top;
      border-bottom: 1px dashed transparent;
    }

    &-textArea {
      .@{i18n-input-prefix-cls}-tag {
        margin-top: 4px;
      }
    }
  }

  &-del {
    padding: 0 4px 0 14px;
    font-size: 14px;
    color: #80838a !important;
    cursor: pointer;
  }

  &-tag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 20px;
    margin-top: 7px;
    padding: 0 4px;
    line-height: 20px;
    font-size: 12px;
    color: #41464f;
    background: #fcfdfe;
    border: 1px solid #eaedf1;
    border-radius: 4px;
    word-break: normal;
    box-sizing: border-box;

    &-require {
      color: #f53f3f;
    }
  }

  &-add-lang {
    display: inline-flex;
    margin-top: 10px;
    font-size: 13px;
    font-weight: 500;
    color: #1664ff;
    cursor: pointer;

    &-icon {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 20px;
      height: 20px;
      margin-right: 8px;
      font-size: 12px;
      background: rgba(162, 193, 255, 0.2);
      border-radius: 20px;
    }

    &--disabled {
      color: #a0c0ff;
      pointer-events: none;
    }
  }

  &-errorMsg {
    font-size: 12px;
    line-height: 20px;
    color: #db373f;
  }
}

.arco-volc3-form-item-status-error .@{tod-prefix}-i18n-input {
  .@{tod-prefix}-i18n-input-box {
    border-color: #fa9ea3;
    background-color: #feeced;

    &:hover {
      border-color: #db373f;
    }

    &.@{tod-prefix}-i18n-input-box--focus {
      box-shadow: 0 0 0 2px rgb(219 55 63 / 30%);
      border-color: #c43138;
      background: #fff;
    }
  }

  .arco-volc3-input:not(.arco-volc3-input-disabled),
  .arco-volc3-textarea:not(.arco-volc3-textarea-disabled) {
    border: none;
    background-color: transparent;
    box-shadow: none;

    &:focus,
    &:hover,
    &:focus:hover {
      border: none;
      background-color: transparent;
      box-shadow: none;
    }
  }
}

.@{arco-prefix}-form-item-status-error .@{tod-prefix}-i18n-input {
  .@{tod-prefix}-i18n-input-box {
    border-color: #fa9ea3;
    background-color: #feeced;

    &:hover {
      border-color: #db373f;
    }

    &.@{tod-prefix}-i18n-input-box--focus {
      box-shadow: 0 0 0 2px rgb(219 55 63 / 30%);
      border-color: #c43138;
      background: #fff;
    }
  }

  .@{arco-prefix}-input:not(.@{arco-prefix}-input-disabled),
  .@{arco-prefix}-textarea:not(.@{arco-prefix}-textarea-disabled) {
    border: none;
    background-color: transparent;
    box-shadow: none;

    &:focus,
    &:hover,
    &:focus:hover {
      border: none;
      background-color: transparent;
      box-shadow: none;
    }
  }
}

.@{tod-prefix}-i18n-input-form-item.@{tod-prefix}-i18n-input-form-item--show-extra {
  .arco-volc3-form-message,
  .@{arco-prefix}-form-message {
    min-height: 20px;
    height: 20px;
    line-height: 20px;

    & + .@{arco-prefix}-form-extra,
    & + .arco-volc3-form-extra {
      margin-bottom: 8px !important;
    }
  }
}
