@import '../../../style/default.less';
@import '../../../style/mixin.less';

@preFixCls: ~'@{vod-prefix}-pageHeader';
@bg: .colorFix(color-bg-white) [ @res];
@title-color: .colorFix(color-text-1) [ @res];
@icon-color: .colorFix(color-fill-3) [ @res];
@subTitle-color: .colorFix(color-text-3) [ @res];
@subTitle-label-color: .colorFix(color-text-3) [ @res];
@subTitle-value-color: .colorFix(color-text-2) [ @res];

.@{preFixCls} {
  background: @bg;

  &-transparent {
    background: transparent;
  }

  &-heading {
    display: flex;
    align-items: center;
    padding: 0 32px;

    &-left {
      display: block;
      flex: 1;
      align-items: center;
    }

    &-breadcrumb {
      padding-top: 20px;
      display: block;
      width: 100%;

      &:first-child:last-child {
        padding: 20px 0;
      }

      .@{arco-prefix}-volc3-link,
      .@{arco-prefix}-link {
        font-size: 12px;
      }
    }

    &-content {
      display: flex;
      padding: 8px 0 20px 0;
      align-items: center;
      width: 100%;

      &:first-child:last-child {
        padding: 20px 0;
      }
    }

    &-backIcon {
      display: inline-flex;
      align-items: center;
      margin-right: 8px;
      font-size: 20px;
      color: @icon-color;
      cursor: pointer;
    }

    &-title-area {
      flex: 1;
      width: 0;
      padding-right: 12px;
      box-sizing: border-box;
    }

    &-title-top {
      display: flex;
      align-items: center;
      width: 100%;
      overflow: hidden;
      white-space: nowrap;
    }

    &-subTitle {
      display: flex;
      height: 20px;
      line-height: 20px;
      font-size: 12px;
      letter-spacing: 0.003em;
      color: @subTitle-color;
      overflow: hidden;
      flex-wrap: nowrap;
      white-space: nowrap;

      &-space {
        display: inline-flex;
        margin-right: 20px;
      }

      &-label {
        margin-right: 2px;
        color: @subTitle-label-color;
      }

      &-value {
        color: @subTitle-value-color;
      }
    }

    &-titleIcon {
      display: flex;
      align-items: center;
      margin-right: 12px;
      font-size: 28px;

      &--hasSubTitle {
        font-size: 40px;
      }
    }

    &-title {
      font-weight: 500;
      font-size: 18px;
      line-height: 28px;
      color: @title-color;
      margin-right: 12px;
      max-width: 100%;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    &-extra {
      padding: 20px 0;
      align-self: flex-end;

      &-space {
        display: inline-flex;
        margin-right: 12px;

        &:last-child {
          margin-right: 0;
        }
      }
    }

    &--hasSubTitle {
      .@{preFixCls}-heading-extra {
        padding: 28px 0;
      }
    }
  }

  &-footer {
    & > .@{arco-prefix}-volc3-tabs > .@{arco-prefix}-volc3-tabs-header-nav-card-gutter,
    & > .@{arco-prefix}-tabs > .@{arco-prefix}-tabs-header-nav-card-gutter {
      padding-left: 32px;
      padding-right: 32px;
    }

    .@{arco-prefix}-volc3-tabs-card-gutter,
    .@{arco-prefix}-tabs-card-gutter {
      .@{arco-prefix}-volc3-tabs-content,
      .@{arco-prefix}-tabs-content {
        border: none;
      }
    }
  }
}
