@import '../../style/default.less';

@priority-tag-prefix-cls: ~'@{tod-prefix}-priority-tag';

@priority-tag-color-default-bg: #eceded;
@priority-tag-color-default: #80838a;
@priority-tag-color-P0-bg: #feeced;
@priority-tag-color-P0: #db373f;
@priority-tag-color-P1-bg: #fdf3de;
@priority-tag-color-P1: #f2a200;
@priority-tag-color-P2-bg: #e2f5eb;
@priority-tag-color-P2: #1cb267;
@priority-tag-color-P3-bg: #ecf2ff;
@priority-tag-color-P3: #1664ff;
@priority-tag-color-urgent-bg: #feeced;
@priority-tag-color-urgent: #db373f;

.status (@status) {
  &--@{status} {
    color: ~'@{priority-tag-color-@{status}}';
    background: ~'@{priority-tag-color-@{status}-bg}';
  }
}

.@{priority-tag-prefix-cls} {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 5px;
  border-radius: 2px;
  font-style: normal;
  font-weight: 500;
  font-size: 12px;

  &-icon {
    margin-right: 4px;
    font-size: 12px;

    svg {
      display: inline-block;
      color: inherit;
      font-style: normal;
      width: 1em;
      height: 1em;
      vertical-align: -2px;
    }
  }

  .status(default);
  .status(P0);
  .status(P1);
  .status(P2);
  .status(P3);
  .status(urgent);
}
