@import '@cloud-ui-react/common-lib/es/style/vars.less';
@import '@cloud-ui-react/common-lib/es/style/automic.less';
@import '@arco-design/web-react/es/style/theme/default.less';
@import '../../style/default.less';

@input-tag-remote-employee-prefix-cls: tod-input-tag-remote-employee;

.@{input-tag-remote-employee-prefix-cls}-item-wrap {
  height: 50px !important;
  &:hover{
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-4');
  }
}

.@{input-tag-remote-employee-prefix-cls}-input-tag-wrap {
  .@{input-tag-remote-employee-prefix-cls}-input-tag {
    margin: 0 0 0 0;

    .@{input-tag-remote-employee-prefix-cls}-input-tag-avatar {
      width: 16px;
      height: 16px;
      border-radius: 50%;
      vertical-align: middle;
      margin: -2px 4px 0 0;
    }

    .@{input-tag-remote-employee-prefix-cls}-input-tag-email {
      margin: 0 0 0 4px;
      color: var(~'@{tod-cssvars-prefix}-color-text-2');
    }
  }
}

.@{input-tag-remote-employee-prefix-cls}-option-item-wrap {
  height: 50px !important;

  .@{input-tag-remote-employee-prefix-cls}-option-item {
    display: flex;
    align-items: center;
    height: 100%;

    .@{input-tag-remote-employee-prefix-cls}-option-avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      vertical-align: middle;
      margin-right: 15px;
    }

    .@{input-tag-remote-employee-prefix-cls}-option-user-info {
      height: 100%;
      line-height: 1;

      p {
        margin: 0;
        font-weight: 400;

        &.@{input-tag-remote-employee-prefix-cls}-option-user-info-name {
          margin: 8px 0 4px;
        }
      }

      .@{input-tag-remote-employee-prefix-cls}-option-user-info-name-inner {
        margin-right: 4px;
      }

      .@{input-tag-remote-employee-prefix-cls}-option-user-info-summary {
        margin: 8px 0 6px;
        font-size: 12px;
        color: var(~'@{tod-cssvars-prefix}-color-text-2');
      }

      .@{input-tag-remote-employee-prefix-cls}-option-user-info-name-resign {
        margin: 0 4px;
        color: rgb(var(~'@{tod-cssvars-prefix}-red-1'));
        padding-left: 4;
      }
    }
  }
}

.arco-select-popup .arco-select-option-disabled {
  .@{input-tag-remote-employee-prefix-cls}-option-user-info-summary {
    color: inherit !important;
  }
}

// 多租户样式

@input-tag-remote-employee-multi-tenant-prefix-cls: tod-input-tag-remote-employee-multi-tenant;

.@{input-tag-remote-employee-multi-tenant-prefix-cls}-item-wrap {
  height: 72px !important;
  font-size: 13px;
  line-height: 20px;
  &:hover{
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-4');
  }
}

.@{input-tag-remote-employee-multi-tenant-prefix-cls}-input-tag-wrap {
  .@{input-tag-remote-employee-multi-tenant-prefix-cls}-input-tag {
    margin: 0 0 0 0;

    .@{input-tag-remote-employee-multi-tenant-prefix-cls}-input-tag-avatar {
      width: 16px;
      height: 16px;
      border-radius: 50%;
      vertical-align: middle;
      margin: -2px 4px 0 0;
    }

    .@{input-tag-remote-employee-multi-tenant-prefix-cls}-input-tag-email {
      margin: 0 0 0 4px;
      color: var(~'@{tod-cssvars-prefix}-color-text-2');
    }
  }
}

.@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-item-wrap {
  height: 72px !important;

  .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-item {
    display: flex;
    align-items: center;
    height: 100%;

    .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-avatar {
      width: 30px;
      height: 30px;
      border-radius: 50%;
      vertical-align: middle;
      margin-right: 15px;
    }

    .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-user-info {
      height: 100%;
      line-height: 20px;
      display: flex;
      flex-direction: column;
      justify-content: center;

      p {
        margin: 0;
        font-weight: 400;
      }

      .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-user-info-name-inner {
        display: flex;
        gap:8px;
        align-items: center;
      }

      .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-user-info-summary {
        font-size: 13px;
        color: var(~'@{tod-cssvars-prefix}-color-text-2');
      }

      .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-user-info-name-resign {
        margin: 0 4px;
        color: rgb(var(~'@{tod-cssvars-prefix}-red-1'));
        padding-left: 4;
        .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-user-info-name-tenant-tag{
          line-height: 18px;
          font-size: 10px;
          height: 18px;
          background-color: transparent;
          border: 1px solid var(~'@{tod-cssvars-prefix}-color-text-4');
        }
      }
    }
  }
}

.arco-select-popup .arco-select-option-disabled {
  .@{input-tag-remote-employee-multi-tenant-prefix-cls}-option-user-info-summary {
    color: inherit !important;
  }
}
