@import '../../style/default.less';
@import '../../XOverflowText/style/index.less';

@sub-title-label-color: var(~'@{tod-cssvars-prefix}-color-text-3');
@sub-title-value-color: var(~'@{tod-cssvars-prefix}-color-text-2');
@sub-title-more-color: var(~'@{tod-cssvars-prefix}-color-text-2');
@sub-title-more-color_bg: var(~'@{tod-cssvars-prefix}-color-bg-1');
@sub-title-more-color_border: var(~'@{tod-cssvars-prefix}-color-border-3');

.@{tod-prefix}-overflow-sub-title {
  width: 100%;

  &-space {
    display: flex;
    height: 20px;
    margin-right: 20px;
    white-space: nowrap;
    font-size: 12px;
  }

  &-label {
    margin-right: 2px;
    color: @sub-title-label-color;
  }

  &-value {
    color: @sub-title-value-color;
  }

  &-more {
    &__trigger {
      flex-shrink: 0;
      display: inline-flex;
      align-items: center;
      height: 20px;
      padding: 0 6px;
      font-size: 12px;
      font-weight: 500;
      color: @sub-title-more-color;
      background: @sub-title-more-color_bg;
      cursor: pointer;
      border: 1px solid @sub-title-more-color_border;
      border-radius: 20px;
      box-sizing: border-box;
    }

    &-popover {
      .arco-volc3-popover-content,
      .arco-popover-content {
        padding: 8px 0 8px 12px;
      }
    }

    &__droplist {
      max-height: 263px;
      padding-right: 8px;
      overflow-y: auto;

      &-item {
        margin-bottom: 8px;

        &:last-child {
          margin-bottom: 0;
        }
      }
    }
  }
}

.@{tod-prefix}-oi-sub-overflow-wrap {
  width: 100%;
  display: flex;
  flex-wrap: nowrap;
}

.@{tod-prefix}-oi-sub-overflow-hidden-item,
.@{tod-prefix}-oi-sub-overflow-item-mirror {
  position: absolute !important;
  white-space: nowrap;
  visibility: hidden;
  pointer-events: none;
}
