@import '../../style/default.less';

.@{tod-prefix}-text-link {
  a {
    text-decoration: none;
    color: inherit;
    cursor: pointer;
  }

  a:hover {
    color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
  }

  &-important {
    a {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    }
  }

  &-with-popover {
    a,
    span {
      cursor: pointer;
      border-bottom: 1px dashed;
    }
  }

  &-expected {
    a {
      border-bottom: 1px solid;
    }
  }

  &-popover {
    .@{arco-prefix}-popover-content {
      max-height: 100px;
      overflow-y: scroll;
    }
  }
}
