@import '../../../style/default.less';
@import '../../../style/mixin.less';

@rd-radioPicker-btn-color: .colorFix(color-text-2) [ @res];
@rd-radioPicker-btn-bg: .colorFix(color-bg-1) [ @res];
@rd-radioPicker-btn-border: .colorFix(color-border-3) [ @res];
@rd-radioPicker-btn-border--hover: rgb(.colorFix(primary-3) [ @res]);
@rd-radioPicker-btn-border--disabled: .colorFix(color-border-2) [ @res];
@rd-radioPicker-btn-color--checked: rgb(.colorFix(primary-6) [ @res]);
@rd-radioPicker-btn-bg--checked: .colorFix(color-link-light-1) [ @res];
@rd-radioPicker-btn-color--disabled: .colorFix(color-fill-1) [ @res];
@rd-radioPicker-btn-color--checked--disabled: rgb(.colorFix(primary-3) [ @res]);

.@{vod-prefix}-radio-picker {
  padding-left: 0;

  &-btn {
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    padding: 0 20px;
    gap: 10px;
    line-height: 30px;
    color: @rd-radioPicker-btn-color;
    font-size: 13px;
    background: @rd-radioPicker-btn-bg;
    border-radius: 4px;
    border: 1px solid @rd-radioPicker-btn-border;
    outline: none;
    cursor: pointer;
    box-sizing: border-box;
    transition: all 0.1s linear;

    &:hover,
    &-checked {
      border-color: @rd-radioPicker-btn-border--hover;
    }

    &-checked {
      color: @rd-radioPicker-btn-color--checked;
      font-weight: 500;
      background: @rd-radioPicker-btn-bg--checked;
    }

    &-disabled {
      color: @rd-radioPicker-btn-color--disabled;
      border-color: @rd-radioPicker-btn-border--disabled;
      cursor: not-allowed;

      &:hover {
        border-color: @rd-radioPicker-btn-border--disabled;
      }
    }

    &-disabled&-checked {
      color: @rd-radioPicker-btn-color--checked--disabled;
      border-color: @rd-radioPicker-btn-border--hover;
    }

    &-mini {
      font-size: 12px;
      line-height: 24px;
      .btn-icon {
        font-size: 24px;
      }
    }

    &-small {
      line-height: 28px;
      .btn-icon {
        font-size: 28px;
      }
    }

    &-large {
      line-height: 36px;
      .btn-icon {
        font-size: 36px;
      }
    }
  }

  &-group {
    .@{vod-prefix}-radio-picker:not(:last-child) {
      margin-right: 8px;
    }

    .@{vod-prefix}-radio-picker {
      margin-right: 0;
    }

    &.@{arco-prefix}-radio-group-direction-vertical,
    &.@{arco-prefix}-volc3-radio-group-direction-vertical {
      .@{vod-prefix}-radio-picker:not(:last-child) {
        margin-right: 0;
        margin-bottom: 8px;
      }
    }
  }
}
