@import '../../style/default.less';


.@{tod-prefix}-form-group {
  &-title {
    margin-bottom: 8px;
    font-size: 13px;
    line-height: 22px;
    color: #41464f;
  }

  .arco-volc3-collapse,
  .@{arco-prefix}-collapse {
    border: none;
  }

  .arco-volc3-form-label-item > label,
  .@{arco-prefix}-form-label-item > label {
    color: #80838a;
  }

  &-item {
    margin-bottom: 12px;
    background: #fcfdfe;

    &.arco-volc3-collapse-item,
    &.@{arco-prefix}-collapse-item {
      border-bottom: none;
    }

    .arco-volc3-collapse-item-header,
    .@{arco-prefix}-collapse-item-header {
      border: 1px solid #eaedf1;
      border-radius: 4px;
    }

    &.arco-volc3-collapse-item-active,
    &.@{arco-prefix}-collapse-item-active {
      > .@{arco-prefix}-collapse-item-header,
      > .arco-volc3-collapse-item-header {
        border: 1px solid #eaedf1;
        border-bottom-color: transparent;
        border-radius: 4px 4px 0 0;
        box-shadow: 0 2px 6px rgba(0, 0, 0, 0.05);
        z-index: 1;

        .@{arco-prefix}-collapse-item-header-title,
        .arco-volc3-collapse-item-header-title {
          font-weight: normal;
        }
      }
    }

    .@{arco-prefix}-collapse-item-content-box,
    .arco-volc3-collapse-item-content-box {
      padding: 16px 20px;
      background: #fcfdfe;
      border: 1px solid #eaedf1;
      border-top: none;
      border-radius: 0 0 4px 4px;
    }
  }

  &-space {
    display: flex;
    align-items: flex-end;
    margin-bottom: 12px;

    .@{arco-prefix}-space,
    .arco-volc3-space {
      flex: 1;
    }

    &-del {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 18px;
      height: 18px;
      font-size: 16px;
      border-radius: 4px;
      vertical-align: bottom;
      color: #80838a;
      margin-left: 8px;
      margin-bottom: 8px;
      cursor: pointer;

      &:hover {
        background: rgba(160, 162, 167, 0.12);
      }
    }

    .@{arco-prefix}-space-item,
    .arco-volc3-space-item {
      flex: 1 1 0%;

      .@{arco-prefix}-form-item,
      .arco-volc3-form-item {
        margin-bottom: 0;
      }

      .arco-volc3-select-single .arco-volc3-select-view-selector,
      .@{arco-prefix}-select-single .arco-select-view-selector {
        position: relative;
        display: inline-flex;
        box-sizing: border-box;
        width: 100%;
        overflow: hidden;

        .arco-volc3-select-view-value-mirror,
        .@{arco-prefix}-select-view-value-mirror {
          opacity: 0;
        }
      }
    }
  }

  &-del {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    vertical-align: middle;
    font-size: 16px;
    border-radius: 4px;
    color: #80838a;
    cursor: pointer;

    &:hover {
      background: rgba(160, 162, 167, 0.12);
    }
  }

  &-add-item {
    display: flex;
    padding-top: 2px;
    font-weight: 500;
    font-size: 13px;
    color: #1664ff;
    cursor: pointer;

    &-icon {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 20px;
      height: 20px;
      margin-right: 8px;
      font-size: 12px;
      background: rgba(162, 193, 255, 0.2);
      border-radius: 20px;
    }
  }
}

.@{tod-prefix}-form-group-tab {
  padding: 0 20px 16px 20px;
}
