@tree-max-width: 500px;

.tod-byte-tree-tree-spin {
  > .arco-spin-children {
    // 限制 Tree 组件高度
    height: 100%;
  }
}
.tod-byte-tree-tab-pane-tree {
  .arco-tree-node {
    position: relative;
    .star {
      box-sizing: content-box;
      position: absolute;
      // icon 高度固定 30px
      top: calc(50% - 15px);
      right: 17px;
      padding: 6px;
      opacity: 0;
      pointer-events: none;
    }

    &:hover .star {
      opacity: 1;
      pointer-events: initial;
    }

    .arco-tree-node-title {
      flex: 1;
      padding-right: 50px;
      width: 0px;
      .arco-tree-node-title-text {
        display: block;
      }
    }
  }

  &.tod-byte-tree-scroll-x {
    > div {
      width: @tree-max-width;

      > div {
        width: @tree-max-width;
      }
    }
  }
}
