@import '../../style/default.less';

@notification-prefix-cls: ~'@{tod-prefix}-notification';

.@{notification-prefix-cls} {
  padding: 16px 20px !important;
  box-sizing: border-box !important;
  position: relative;

  // 对于有卡片布局的通知，移除底部边距
  &:has(.@{notification-prefix-cls}-detail-wrapper) {
    padding-bottom: 0 !important;
  }

  .@{notification-prefix-cls}-detail-wrapper {
    border: none;
    border-radius: 4px;
    max-height: 315px;
    display: flex;
    flex-direction: column;
    padding-bottom: 16px;

    &.@{notification-prefix-cls}-detail-wrapper-auto-height {
      height: auto;
    }

    .@{notification-prefix-cls}-detail-inner-wrapper {
      flex: 1 1 auto;
      overflow-y: auto;
      display: flex;
      flex-direction: column;
      box-sizing: border-box;

      .@{notification-prefix-cls}-detail-scrollable-content {
        display: flex;
        flex-direction: column;
        flex: 1;
      }

      &::-webkit-scrollbar {
        width: 10px;
        height: 12px;
      }

      &::-webkit-scrollbar-thumb {
        border-radius: 10px;
        background-color: var(~'@{tod-cssvars-prefix}-color-fill-1');
        border: 2px solid transparent;
        background-clip: padding-box;
      }

      &::-webkit-scrollbar-thumb:hover {
        background-color: var(~'@{tod-cssvars-prefix}-color-fill-2');
      }

      .@{notification-prefix-cls}-detail-message {
        font-size: 13px;
        margin-bottom: 8px;
      }

      .@{notification-prefix-cls}-detail-content {
        flex: 1;
        box-sizing: border-box;
        font-size: 12px;
        max-width: 100%;
        height: auto;
        margin: 0 0 5px;
        background-color: rgb(from #f1f3f5 r g b / 0.5);
        padding: 5px;
        border-radius: 4px;
        white-space: pre-wrap;
        word-break: break-word;
        border: 0.5px solid var(~'@{tod-cssvars-prefix}-color-border-3');
        .@{notification-prefix-cls}-detail-label {
          color: var(~'@{tod-cssvars-prefix}-color-text-3');
        }
      }
    }

    .@{notification-prefix-cls}-detail-actions {
      width: 100%;
      height: 24px;
      box-sizing: border-box;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-shrink: 0;
      
      > div:first-child {
        display: flex;
        align-items: center;
        margin: 0;
        padding: 0;
      }
      
      > div:last-child {
        margin-right: 0;
      }
    }
    
    // 当检测到有滚动条时，增加整个actions区域的右侧padding
    .@{notification-prefix-cls}-detail-inner-wrapper.has-scrollbar ~ .@{notification-prefix-cls}-detail-actions {
      padding-right: 10px;
    }
  }

  .@{notification-prefix-cls}-resize-grabber {
    width: 100%;
    height: 12px;
    cursor: ns-resize;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: opacity 0.2s ease;
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;

    .@{notification-prefix-cls}-resize-grabber-inner {
      width: 12px;
      height: 4px;
      border-top: 1px solid var(~'@{tod-cssvars-prefix}-color-text-3');
      border-bottom: 1px solid var(~'@{tod-cssvars-prefix}-color-text-3');
      opacity: 0;
    }

    &:hover .@{notification-prefix-cls}-resize-grabber-inner,
    &.@{notification-prefix-cls}-resize-grabber-dragging .@{notification-prefix-cls}-resize-grabber-inner {
      opacity: 1;
    }
  }

  .@{notification-prefix-cls}-doc-link {
    color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    text-decoration: none;

    &:visited {
      color: rgb(var(~'@{tod-cssvars-prefix}-purple-6'));
    }
  }

  .@{notification-prefix-cls}-oncall-button {
    width: 14px !important;
    height: 14px !important;
    font-size: 14px !important;
    min-width: 14px !important;
    padding: 0 !important;
    border: none !important;
  }
  .@{notification-prefix-cls}-copy-button{
    width: 14px !important;
    height: 14px !important;
    font-size: 14px !important;
    min-width: 14px !important;
    padding: 0 !important;
    border: none !important;
    margin-right: 12px !important;
    margin-left: 0 !important;
    
    &:disabled {
      margin-right: 12px !important;
      margin-left: 0 !important;
    }
  }
}
