@import '../../style/default.less';
@import '../../XAvatar/style/index.less';

.@{tod-prefix}-principal-universal-search-option-item {
  display: flex;
  gap: 5px;
  align-items: center;
  .@{tod-prefix}-pure-avatar{
    width: 20px !important;
    height: 20px !important;
    background-color: var(~'@{tod-cssvars-prefix}-color-fill-1');
  }
 
}
.@{tod-prefix}-principal-universal-search-render-tag-user{
  .@{tod-prefix}-pure-avatar{
    width: 18px !important;
    height: 0 !important;
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-1');;
  }
  .@{arco-prefix}-avatar-image{
    width: 18px !important;
    height: 18px;
  }
}

.@{tod-prefix}-principal-universal-search-render-tag{
  .@{tod-prefix}-pure-avatar{
    width: 18px !important;
    height: 18px !important;
    background-color: inherit;
  }
  svg{
    background-color: inherit !important;
    vertical-align: middle;
  }
  line-height: 30px;
}
