@import '../../style/default.less';

@xCloudSiteTagSitePrefix: ~'@{tod-prefix}-x-cloud-site-tag';

.common-site-tag(){
  display: inline-flex;
  align-items: center;
  color: rgb(var(~'@{tod-cssvars-prefix}-color-text-1'));
  .vod-tag-pro.vod-tag-pro-big .vod-tag{
    font-weight: 400;
  }
}

.@{xCloudSiteTagSitePrefix}-site-wrap-small{
  .common-site-tag();
  gap:5px;
  font-size: 13px;
  line-height: 22px;
  .@{xCloudSiteTagSitePrefix}-site-flag{
    width: 16px;
    height: 16px;
    font-size: 16px;
    line-height: 16px;
    border-radius: 50%;
  }
}

.@{xCloudSiteTagSitePrefix}-site-wrap{
  .common-site-tag();
  gap:8px;
  font-size: 13px;
  line-height: 22px;
  .@{xCloudSiteTagSitePrefix}-site-flag{
    width: 18px;
    height: 18px;
    font-size: 18px;
    line-height: 18px;
    border-radius: 50%;
  }

}

.common-env-tag(){
  display: inline-block;
  border-radius: 4px;
  color: rgb(var(~'@{tod-cssvars-prefix}-color-text-1'));
}

.@{xCloudSiteTagSitePrefix}-env-tag{
  .common-env-tag();
  font-size: 12px;
  font-weight: 500;
  line-height: 18px;
  padding: 0 4px;
}

.@{xCloudSiteTagSitePrefix}-env-tag-small{
  .common-env-tag();
  font-size: 10px;
  font-weight: 500;
  line-height: 16px;
  padding: 0 6px;
}


.@{xCloudSiteTagSitePrefix}-vregion-tag{
  max-width: 100%;
  display: inline-flex;
  gap: 6px;
  align-items: center;
  font-size: 13px;
  line-height: 22px;
  color: rgb(var(~'@{tod-cssvars-prefix}-color-text-1'));
  .@{xCloudSiteTagSitePrefix}-vregion-flag{
    width: 18px;
    height: 18px;
    font-size: 16px;
    line-height: 18px;
    flex-shrink: 0;
  }
  .@{xCloudSiteTagSitePrefix}-vregion-tag-name{
    flex: 1;
    overflow: hidden;
  }
  .vod-tag-pro.vod-tag-pro-big .vod-tag{
    font-weight: 400;
    flex-shrink: 0;
  }
}
