@import './vars.less';
// font size
.generate-fs(18);
.generate-fs(@n, @i: 12) when (@i <= @n) {
  .f-s-@{i} {
    font-size: @i * 1px;
  }
  .generate-fs(@n, @i + 1);
}

// color
.color-map() {
  danger: @danger-color;
  warning: @warning-color;
  info: @primary-color;
  success: @success-color;
};
each(.color-map(), .(@v, @k) {
  .color-@{k} {
    color: @v;
  }
  .bg-@{k} {
    background-color: @v;
  }
});

.color-grey {
  color: @color-font-light;
}

.color-f-black {
  color: @color-font-black;
}

