@import '../../style/default.less';

.@{ve-o-prefix}-standard-drag-upload-box {
  width: 480px;
  display: flex;
  flex-direction: column;
  .@{ve-o-prefix}-upload-list-type-picture-card {
    order: 3;
    margin-top: 20px;
  }
  .@{ve-o-prefix}-upload-trigger-tip {
    order: 2;
    margin-top: 20px;
  }
}
.@{ve-o-prefix}-standard-drag-upload-trigger {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-flow: column;
  width: 480px;
  height: 212px;
  text-align: center;
  background-color: var(~'@{arco-cssvars-prefix}-color-bg-4');
  border: 1px dashed var(~'@{arco-cssvars-prefix}-color-border-3');

  &-icon-wrap {
    font-size: 44px;
    line-height: 44px;
  }
  &-text-wrap {
    // width: 194px;
  }
  &-title {
    margin: 0;
    line-height: 24px;
    margin-bottom: 4px;
  }
  &-desc {
    display: inline-block;
    font-size: 12px;
    color: var(~'@{arco-cssvars-prefix}-color-text-3');
    line-height: 20px;
  }
}
