@import '../../style/default.less';
@import '../../style/mixin.less';

@uiPrefix: ~'@{vod-prefix}-iconButton';

@color--hover: var(--veo-iconButton-hover-color);
@color--active: var(--veo-iconButton-active-color);
@color--icon: .colorFix(color-text-1) [ @res];
@color--disabled: .colorFix(color-fill-1) [ @res];

body {
  --veo-iconButton-hover-color: rgba(2, 8, 20, 0.05);
  --veo-iconButton-active-color: rgba(2, 8, 20, 0.1);
}

body[arco-theme='dark'] {
  --veo-iconButton-hover-color: rgba(255, 255, 255, 0.05);
  --veo-iconButton-active-color: rgba(255, 255, 255, 0.1);
}

.@{uiPrefix} {
  display: inline-block;
  padding: 4px;
  color: @color--icon;
  outline: none;
  border: none;
  appearance: none;
  user-select: none;
  cursor: pointer;
  white-space: nowrap;
  text-align: center;
  transition: all 0.1s cubic-bezier(0, 0, 1, 1);
  box-sizing: border-box;
  background: none;
  border-radius: 4px;

  &:not(.@{prefix}--disabled):not(.@{prefix}--loading):hover {
    background: @color--hover;
  }

  &:not(.@{prefix}--disabled):not(.@{prefix}--loading):active {
    background: @color--active;
  }

  svg {
    vertical-align: top;
  }

  &--mini {
    width: 20px;
    height: 20px;
    line-height: 20px;
    font-size: 12px;
  }

  &--small {
    width: 22px;
    height: 22px;
    line-height: 22px;
    font-size: 14px;
  }

  &--default {
    width: 24px;
    height: 24px;
    line-height: 24px;
    font-size: 16px;
  }

  &--medium {
    width: 32px;
    height: 32px;
    padding: 6px;
    line-height: 32px;
    font-size: 20px;
  }

  &--large {
    width: 36px;
    height: 36px;
    padding: 6px;
    line-height: 36px;
    font-size: 24px;
  }

  &--disabled {
    color: @color--disabled;
    cursor: not-allowed;
  }

  &--loading {
    cursor: default;
  }
}
