/* stylelint-disable declaration-colon-newline-after */
@import '../../style/default.less';
@import '@arco-design/web-react/es/style/theme/default.less';

@oncall-prefix-cls: ~'@{tod-prefix}-oncall';

@modal-prefix-cls: ~'@{prefix}-modal';
@typography-prefix-cls: ~'@{prefix}-typography';

.@{oncall-prefix-cls}-trigger {
  position: fixed;
  top: calc(60vh + 19px);
  right: 0;
  z-index: 1002;
  display: flex;
  align-items: center;
  box-sizing: content-box;
  height: 22px;
  padding: 9px 25px 9px 5px;
  color: var(~'@{tod-cssvars-prefix}-color-white');
  white-space: nowrap;
  background: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
  border-radius: 4px 0 0 4px;
  transform: translateX(calc(100% - 26px));
  cursor: pointer;
  transition: transform 0.3s ease;
  user-select: none;

  &&-draggable {
    cursor: move;
    top: 45%;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 25px;
    height: unset;
    padding: 10px 6px;
    line-height: 1.5;
    box-sizing: border-box;
    white-space: unset;
    transition: unset;

    .@{oncall-prefix-cls}-trigger-icon {
      font-size: 13px;
    }

    .@{oncall-prefix-cls}-trigger-text {
      word-wrap: break-word;
      font-size: 13px;
      width: 100%;
      margin: 4px 0 0;
      text-align: center;
    }
  }

  &-icon {
    font-size: 16px;
  }

  &-text {
    margin-right: 5px;
    margin-left: 5px;
    font-weight: 500;
    font-size: 13px;
  }

  &:hover {
    transform: translateX(20px);
  }
}

.@{oncall-prefix-cls}-modal {
  &.@{modal-prefix-cls} {
    width: unset;
  }
  .@{modal-prefix-cls}-content {
    padding: 0;
  }
}

.@{oncall-prefix-cls}-content {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  width: 1000px;
  height: 640px;
  padding: 20px 24px;
  background: linear-gradient(
      82.57deg,
      rgba(255, 255, 255, 0.25) 34.68%,
      rgba(255, 255, 255, 0) 100%
    ),
    radial-gradient(1146.89% 52.11% at -51.19% 40.7%, rgba(244, 255, 255, 0.46) 7.54%, #f5faff 100%);
  border-radius: 8px;

  &-title.@{typography-prefix-cls} {
    margin: 0;
    font-weight: 500;
    font-size: 18px;
    line-height: 26px;
  }

  &-main {
    display: flex;
    flex: 1;
    margin-top: 20px;
  }

  &-block {
    border-radius: 4px;
    box-shadow: 0 4px 8px rgba(203, 220, 237, 0.3);
  }

  &-left {
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    width: 240px;
    margin-right: 12px;
    padding: 8px;
    background: #fff;
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
  }

  &-right {
    flex: 1;
    overflow: hidden;
  }

  &-item {
    margin: 0;
    padding: 12px;
    background: linear-gradient(130.43deg, #ebfaf8 0%, rgba(255, 255, 255, 0) 23.46%);
    border-radius: 4px;

    dt {
      & > svg {
        margin-right: 8px;
        font-size: 16px;
      }

      display: flex;
      align-items: center;
      height: 22px;
      margin-bottom: 4px;
      color: var(~'@{tod-cssvars-prefix}-color-text-1');
      font-weight: 500;
      font-size: 13px;
      line-height: 22px;
    }

    dd {
      margin: 0;
      margin-top: 8px;
      cursor: pointer;
    }
  }

  &-doc {
    margin-bottom: 8px;
  }

  &-doc_item {
    position: relative;
    padding-left: 12px;

    &::before {
      position: absolute;
      top: 8px;
      left: 2px;
      display: block;
      width: 4px;
      height: 4px;
      background: var(~'@{tod-cssvars-prefix}-color-text-3');
      border-radius: 2px;
      content: '';
    }

    &:hover {
      &::before {
        background: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
      }
    }
  }

  &-doc_item_link_wrap {
    padding: 0;

    &:focus-visible {
      box-shadow: none;
    }
  }

  &-doc_item_link.@{typography-prefix-cls} {
    margin: 0;
    padding: 0;
    color: var(~'@{tod-cssvars-prefix}-color-text-1');

    &:hover {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    }

    &:active {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-7'));
    }
  }

  &-doc_center {
    padding-left: 12px;
  }

  &-doc_center_link {
    padding: 0;
    color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    font-weight: 400;
    font-size: 12px;
    line-height: 20px;

    &:hover {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-5'));
    }

    &:active {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-7'));
    }

    &:focus-visible {
      box-shadow: none;
    }
  }

  &-group_item {
    display: flex;
    gap: 8px;
    align-items: center;
  }

  &-group_item_text.@{typography-prefix-cls} {
    flex: 1;
    margin: 0;
    color: var(~'@{tod-cssvars-prefix}-color-text-1');
    font-weight: 400;
    font-size: 12px;
    line-height: 20px;

    &:hover {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    }

    &:active {
      color: rgb(var(~'@{tod-cssvars-prefix}-primary-7'));
    }
  }
}

body[arco-theme='dark'] {
  .@{oncall-prefix-cls}-content {
    background: var(~'@{tod-cssvars-prefix}-color-bg-1');

    &-left {
      background: var(~'@{tod-cssvars-prefix}-color-bg-2');
    }

    &-item {
      background: linear-gradient(130.43deg, rgb(31, 68, 62) 0%, rgba(42, 41, 40, 0) 23.46%);
    }
  }
}
