@import '@cloud-ui-react/common-lib/es/style/vars.less';
@import '../../../../style/default.less';

@star-cls: ~'@{tod-prefix}-byte-tree-selector-star';

.@{star-cls} {
  &__wrapper {
    .@{star-cls} {
      &__like {
        color: #ff7d00;
      }
      &__like:hover {
        color: rgba(255, 125, 0, 0.85);
      }
      &__unlike {
        color: rgb(var(--gray-8));
      }
      &__unlike:hover {
        color: #ff7d00;
      }
      &__like,
      &__unlike {
        cursor: pointer;
        font-size: 18px;
      }
    }
  }

  .arco-icon {
    fill: none;
  }
}
