@import '../../style/default.less';

.@{tod-prefix}-byte-tree-permission-modal {
  .iam-auth-arco{
    .m-t-8 {
      margin-top: 8px;
    }
  
    .f-s-12 {
      font-size: 12px;
    }
    .color-grey {
      color: rgb(var(~'@{tod-cssvars-prefix}-color-text-2'));
    }
  
    .iam-message-info {
      word-break: break-all;
      margin-bottom: 6px;
    }
  
    .iam-message-alert {
      max-height: 260px;
      overflow-y: auto;
      margin-bottom: 6px;
      padding: 12px;
      background-color: rgb(var(~'@{tod-cssvars-prefix}-warning-1'));
    }
    .code {
      background: var(~'@{tod-cssvars-prefix}-color-fill-1');
      padding: 10px;
      overflow: auto;
      font-weight: 400;
    }
    .arco-alert-with-title{
      display: flex;
    }
    .arco-icon-hover::before{
      display: none;
    }
  }
}

