@import '../../style/default.less';


@log-ansi-prefix: log-ansi;

.@{log-ansi-prefix}.arco,.@{log-ansi-prefix}.arco-theme {
  --log-ansi-border: var(~'@{tod-cssvars-prefix}-color-border-1');
  --log-ansi-bg-1: var(~'@{tod-cssvars-prefix}-color-bg-1');
  --log-ansi-bg-2: var(~'@{tod-cssvars-prefix}-color-bg-2');
  --log-ansi-bg-3: var(~'@{tod-cssvars-prefix}-color-bg-3');
  --log-ansi-bg-4: var(~'@{tod-cssvars-prefix}-color-bg-4');
  --log-ansi-bg-highlight: rgb(var(~'@{tod-cssvars-prefix}-yellow-6'));
  --log-ansi-bg-highlight-focus: rgb(var(~'@{tod-cssvars-prefix}-orange-6'));
  --log-ansi-text-1: var(~'@{tod-cssvars-prefix}-color-text-1');
  --log-ansi-text-2: var(~'@{tod-cssvars-prefix}-color-text-2');
  --log-ansi-text-3: var(~'@{tod-cssvars-prefix}-color-text-3');
  --log-ansi-text-4: var(~'@{tod-cssvars-prefix}-color-text-4');
  --log-ansi-text-highlight: var(~'@{tod-cssvars-prefix}-color-black');
  --log-ansi-hover: var(~'@{tod-cssvars-prefix}-color-neutral-3');
  --log-ansi-link: rgb(var(~'@{tod-cssvars-prefix}-link-6'));
}

/** Dark Theme **/
.@{log-ansi-prefix}.dark{
  --log-ansi-border: #e5e6eb;
  --log-ansi-bg-1: #17171A;
  --log-ansi-bg-2: #232324;
  --log-ansi-bg-3: #2a2a2b;
  --log-ansi-bg-4: #313132;
  --log-ansi-bg-highlight: #fbe94b;
  --log-ansi-bg-highlight-focus: #f9925a;
  --log-ansi-text-1: #e6e6e6;
  --log-ansi-text-2: #b3b3b3;
  --log-ansi-text-3: #808080;
  --log-ansi-text-4: #4d4d4d;
  --log-ansi-text-highlight: #020814;
  --log-ansi-hover: #4d4d4d;
  --log-ansi-link: #74a2ff;
}

.@{log-ansi-prefix} {
  --log-ansi-border: #e5e6eb;
  --log-ansi-bg-header: #e6e6e6;
  --log-ansi-bg-1: #ffffff;
  --log-ansi-bg-2: #fcfdfe;
  --log-ansi-bg-3: #fafbfc;
  --log-ansi-bg-4: #f6f8fa;
  --log-ansi-bg-highlight: #fadc19;
  --log-ansi-bg-highlight-focus: #f77234;
  --log-ansi-text-1: #020814;
  --log-ansi-text-2: #41464f;
  --log-ansi-text-3: #80838a;
  --log-ansi-text-4: #ccced0;
  --log-ansi-text-highlight: #020814;
  --log-ansi-hover: #f1f3f5;
  --log-ansi-link: #1a6eff;
}

/** 4-bit color: xterm **/
.@{log-ansi-prefix} {
  --log-ansi-black: rgb(0, 0, 0);
  --log-ansi-red: rgb(205, 0, 0);
  --log-ansi-green: rgb(0, 205, 0);
  --log-ansi-yellow: rgb(205, 205, 0);
  --log-ansi-blue: rgb(0, 0, 238);
  --log-ansi-magenta: rgb(205, 0, 205);
  --log-ansi-cyan: rgb(0, 205, 205);
  --log-ansi-white: rgb(229, 229, 229);
  --log-ansi-bright-black: rgb(127, 127, 127);
  --log-ansi-bright-red: rgb(255, 0, 0);
  --log-ansi-bright-green: rgb(0, 255, 0);
  --log-ansi-bright-yellow: rgb(255, 255, 0);
  --log-ansi-bright-blue: rgb(92, 92, 255);
  --log-ansi-bright-magenta: rgb(255, 0, 255);
  --log-ansi-bright-cyan: rgb(0, 255, 255);
  --log-ansi-bright-white: rgb(255, 255, 255);
}

.@{log-ansi-prefix} {
  position: relative;
  border: 1px solid var(--log-ansi-border);
  border-radius: 4px;
}

.@{log-ansi-prefix}-scroller {
  background-color: var(--log-ansi-bg-1);
  color: var(--log-ansi-text-1);
}

.@{log-ansi-prefix}-affix {
  z-index: 10;
  position: absolute;
  right: 32px;
  bottom: 16px;
  display: flex;
  flex-direction: column;
  row-gap: 0.5rem;
}

/** css override for arco button **/
.@{log-ansi-prefix} {
  & .@{log-ansi-prefix}-header .@{log-ansi-prefix}-header-search button {
    color: var(--log-ansi-text-2);
    &:hover {
      background-color: var(--log-ansi-bg-header);
    }
  }
  & .@{log-ansi-prefix}-affix button {
    background-color: var(--log-ansi-bg-4);
    color: var(--log-ansi-text-2);
    &:disabled {
      color: var(--log-ansi-text-4);
    }
  }
}

.@{log-ansi-prefix}-header {
  display: flex;
  column-gap: 1rem;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--log-ansi-border);
  &-meta {
    flex: 1;
    display: flex;
    align-items: stretch;
    column-gap: 1rem;
    &-title {
      font-weight: 500;
      font-size: 1.1rem;
    }
    &-description {
      color: var(--log-ansi-text-2);
    }
  }
  &-search {
    display: flex;
    align-items: center;
    color: var(--log-ansi-text-2);
    &-counter {
      padding: 0 5px;
    }
  }
}

.@{log-ansi-prefix}-line {
  font-size: 12px;
  /* font-family: ui-monospace, SFMono-Regular, 'SF Mono,Menlo', Consolas, 'Liberation Mono', monospace; */
  font-family: Menlo, 'RobotoMono', Monaco, 'Courier New', monospace;
  display: flex;
  background-color: var(--log-ansi-bg-1);
  &:hover {
    background-color: var(--log-ansi-hover);
  }
  a {
    color: var(--log-ansi-link);
  }
  &-highlight {
    background-color: var(--log-ansi-bg-highlight);
    color: var(--log-ansi-text-highlight);
    &-focus {
      background-color: var(--log-ansi-bg-highlight-focus);
    }
  }
}

.@{log-ansi-prefix}-line-number {
  flex: 0 0 48px;
  text-align: right;
  padding: 0 12px;
  user-select: none;
  color: var(--log-ansi-text-2);
}

.@{log-ansi-prefix}-line-content {
  display: flex;
}

.@{log-ansi-prefix}-line-log-content {
  display: inline-block;
  overflow-wrap: break-word;
  word-break: break-word;
  white-space: pre-wrap;
}
