@import '../../style/default.less';

@x-psm-network-status-prefix: ~'@{tod-prefix}-psm-network-status';

.@{x-psm-network-status-prefix} {
    box-sizing: border-box;

    .arco-popover-content {
        width: 400px;
    }

    a {
        text-decoration: none;
        color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
        font-weight: 500;
        font-size: 12px;

    }

    &-content {

        &-item:nth-of-type(1) {
            margin-top: 10px;
        }

        &-item {
            padding-bottom: 12px;
            &-title {
                display: flex;
                align-items: flex-start;
                justify-content: space-between;
                line-height: 22px;
                font-weight: 500;
                font-size: 14px;
                color: var(~'@{tod-cssvars-prefix}-color-text-1');

                &-text {
                    margin-left: 8px;
                    display: inline-block;
                }
            }

            &-desc {
                margin-left: 26px;
                color: var(~'@{tod-cssvars-prefix}-color-text-3');
                font-size: 12px;
                line-height: 20px;

            }
        }
    }
}

.@{x-psm-network-status-prefix}-empty {
    color: var(~'@{tod-cssvars-prefix}-color-text-3');

    .arco-popover-content {
        padding: 0;
    }

    &-content {
        padding: 0;
        background: var(~'@{tod-cssvars-prefix}-color-bg-4');
        height: 200px;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        font-weight: 500;

    }

    &-footer {
        padding: 8px 12px;
    }
    .arco-popover-arrow.arco-trigger-arrow {
        background: var(~'@{tod-cssvars-prefix}-color-bg-4');
    }
}