@import '../../style/default.less';

@ve-o-prefix: @tod-prefix;

.colorFix(@var) {
  @res: var(~'--arco-volc3-@{var}', var(~'--@{var}'));
}

@icon-color: .colorFix(color-text-2) [ @res];
@icon-bg-color--hover: .colorFix(color-fill-4) [ @res];

.@{ve-o-prefix}-editableTable {
  &-row {
    .@{arco-prefix}-table-td {
      vertical-align: top;
    }
  }
}

.@{ve-o-prefix}-editableTable-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  font-size: 16px;
  color: @icon-color;
  border-radius: 4px;
  position: relative;
  cursor: pointer;

  &:hover {
    &::before {
      position: absolute;
      top: 0;
      left: 0;
      display: block;
      content: '';
      width: 100%;
      height: 100%;
      background: @icon-bg-color--hover;
      opacity: 0.05;
      border-radius: 2px;
      pointer-events: none;
    }
  }

  &-close {
    font-size: 16px;
    color: #db373f;
  }

  &-check {
    font-size: 16px;
    color: #1cb267;
  }
}
