
@import '../../style/default.less';

.@{tod-prefix}-table {
  &-text-button {
    &:not(:last-child) {
      margin-right: 12px;
    }
    // @primary-6
    color: rgb(var(~'@{tod-cssvars-prefix}-primary-6'));
    font-size: 12px;
    cursor: pointer;
    &-disabled {
      // @gray-4
      color: rgb(var(~'@{tod-cssvars-prefix}-gray-4'));
      cursor: default;
    }
  }
}