@import '../../style/default.less';

@timezone-select-prefix-cls: ~'@{tod-prefix}-timezone-select';

.@{timezone-select-prefix-cls} {
  &-button {
    box-shadow: none !important;
    border: none !important;
    background-color: unset !important;

    &-open,
    &:hover {
      background-color: var(~'@{tod-cssvars-prefix}-color-bg-4') !important;
    }
  }

  &-item {
    margin: 0 -12px;
    padding: 0 12px;
  }
}
