@import '../../../style/default.less';

@import '../../../style/mixin.less';

@rd-TabsBadge-num-color: .colorFix(color-text-2) [ @res];
@rd-TabsBadge-num-bg: .colorFix(color-bg-3) [ @res];
@rd-TabsBadge-num-color--active: .colorFix(color-link-light-6) [ @res];
@rd-TabsBadge-num-bg--active: .colorFix(color-link-light-2) [ @res];

.@{vod-prefix}-tabs-badge {
  display: flex;
  align-items: center;

  &-num {
    display: inline-block;
    min-width: 14px;
    height: 14px;
    padding: 0 4px;
    margin-left: 4px;
    font-family: 'Inter';
    font-style: normal;
    color: @rd-TabsBadge-num-color;
    font-weight: 500;
    font-size: 10px;
    line-height: 14px;
    text-align: center;
    background: @rd-TabsBadge-num-bg;
    border-radius: 42px;
    box-sizing: border-box;
  }
}

.@{arco-prefix}-tabs-header-title-active,
.@{arco-prefix}-volc3-tabs-header-title-active {
  .@{vod-prefix}-tabs-badge-num {
    color: @rd-TabsBadge-num-color--active;
    background: @rd-TabsBadge-num-bg--active;
  }
}
