@import '../../style/default.less';
@import './variables.less';
@import './mixins.less';
@import '../../XAvatar/style/index.less';

@popup-prefix: ~'@{tod-prefix}-user-profile-popup';
@profileWidth: 320px;
@profileHeight: 480px;

.shrink-transition() {
  transition: all 0.4s cubic-bezier(0.39, 0.58, 0.57, 1);
}
.@{tod-prefix}-user-profile__main {
  border-radius: 8px;
  box-shadow: 0px 8px 24px 8px rgba(31, 35, 41, 0.04), 0px 6px 12px 0px rgba(31, 35, 41, 0.04),
    0px 4px 8px -8px rgba(31, 35, 41, 0.06);
}
body[arco-theme='dark'] {
  .@{tod-prefix}-user-profile__main {
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-3');
  }
}
.@{popup-prefix} {
  width: @profileWidth;
  position: relative;
  height: @profileHeight;
  overflow: hidden;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  justify-content: flex-start;
  background-color: var(~'@{tod-cssvars-prefix}-color-bg-8');
  .scroll-bar();
  &-wheel-section {
    position: relative;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
    overflow: hidden;
    .shrink-transition();
    .@{tod-prefix}-user-profile-popup-header {
      width: 100%;
      height: 136px;
      position: relative;
      flex-shrink: 0;
      .@{tod-prefix}-user-profile-popup-header-cover {
        position: absolute;
        width: 100%;
        height: 100%;
        &-image {
          width: 100%;
          height: 100%;
          object-fit: cover;
          -webkit-user-select: none;
          user-select: none;
          background-color: var(~'@{tod-cssvars-prefix}-color-bg-8');
        }
      }
    }
    .@{tod-prefix}-user-profile-popup-body {
      position: relative;
      width: 100%;
      flex-grow: 1;
      min-height: 0;
      display: flex;
      flex-direction: column;
      flex-wrap: nowrap;
      justify-content: flex-start;
      &-info {
        opacity: 1;
        transition: all 0.4s cubic-bezier(0.39, 0.58, 0.57, 1);
        .@{tod-prefix}-user-profile-popup-body-avatar {
          position: absolute;
          left: 12px;
          top: -48px;
          width: 96px;
          height: 96px;
          border-radius: 50%;
          background-color: var(~'@{tod-cssvars-prefix}-color-bg-8');
          // box-shadow: 0px 4px 8px var(--shadow-default-md);
          &-wrapper {
            box-sizing: border-box;
            width: 100%;
            height: 100%;
            border-radius: 50%;
            border: 3px solid var(~'@{tod-cssvars-prefix}-color-bg-8');
            display: flex;
          }
        }
        .@{tod-prefix}-user-profile-popup-body-username {
          margin: 56px 16px 0;
          line-height: 28px;
          font-size: 20px;
          font-weight: 600;
          word-break: break-word;
          // color: var(--text-title);
          color: var(~'@{tod-cssvars-prefix}-color-text-1');
          display: -webkit-box;
          flex-shrink: 0;
          -webkit-line-clamp: 2;
          -webkit-box-orient: vertical;
          overflow: hidden;
          &-text {
            margin-right: 8px;
          }
        }
        &-main-many-info {
          display: flex;
          flex-direction: column;
          justify-content: flex-start;
          flex-shrink: 0;
          opacity: 1;
          transition: all 0.4s cubic-bezier(0.39, 0.58, 0.57, 1);
        }
      }
      &-content {
        flex-grow: 1;
        overflow: hidden;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        .@{tod-prefix}-user-profile-popup-body-main {
          flex-grow: 1;
          display: flex;
          flex-direction: column;
          justify-content: flex-start;
          overflow: hidden;
        }
        .@{tod-prefix}-user-profile-popup-body-main-desc {
          overflow: hidden;
          margin: 8px 16px 0;
          span {
            font-size: 14px;
            line-height: 22px;
            color: var(~'@{tod-cssvars-prefix}-color-text-3');
          }
        }
        .@{popup-prefix}-body-main-actions {
          margin: 12px 16px 4px 16px;
          display: flex;
          .@{arco-prefix}-btn {
            flex: 1;
          }
        }
        .@{popup-prefix}-body-main-actions.@{popup-prefix}-body-main-actions-multi {
          justify-content: space-between;
          align-items: center;
          .@{arco-prefix}-btn {
            height: 43px;
            margin-right: 6px;
            display: flex;
            align-items: center;
            flex-flow: column;
            justify-content: center;
            span {
              margin: 0;
            }
            &:last-child {
              margin-right: 0;
            }
          }
        }
        .@{popup-prefix}-body-main-container {
          flex-grow: 1;
          width: 100%;
          overflow-y: scroll;
          overflow-x: hidden;
          display: flex;
          flex-direction: column;
          justify-content: space-between;
          // hover 时展示滚动条、非 hover 时不展示滚动条，对 Firefox、低版 ie 等非 webkit 内核的浏览器不生效
          &::-webkit-scrollbar {
            display: none;
          }

          &:hover {
            &::-webkit-scrollbar {
              display: block;
            }
          }
          .@{popup-prefix}-body-main-fields {
            --profile-fields-length: 3;
            box-sizing: border-box;
            font-size: 14px;
            line-height: 20px;
            padding: 16px 0 0 16px;
            width: @profileWidth - 20px; // 预留出滚动条会占据的位置，避免 hover 态、非 hover 态切换时滚动条出现、消失引发重新布局
            display: grid;
            grid-template-columns: max-content auto;
            grid-column-gap: 12px;
            grid-template-rows: repeat(var(--profile-fields-length), max-content);
            grid-row-gap: 16px;
            .@{prefix}-descriptions-item, .@{prefix}-descriptions-item-label, .@{prefix}-descriptions-item-value {
              padding-bottom: 16px;
            }
            .@{prefix}-descriptions-item-value {
              width: 180px;
            }
          }
        }
      }
    }
    .@{tod-prefix}-user-profile__empty {
      height: 100%;
      .@{popup-prefix}-header{
        overflow: hidden;        
        &-fill {
          width: 100%;
          height: 180px;
          background: linear-gradient(180deg, rgba(0, 0, 0, 0.20) 0%, rgba(0, 0, 0, 0.00) 100%);
        }
      }
      .@{popup-prefix}-body {
        height: 384px;
        width: 100%;
        display: flex;
        align-items: center;
        .@{popup-prefix}-body-avatar-wrapper {
          background-color: var(~'@{tod-cssvars-prefix}-color-bg-4');
          box-shadow: 0px 8px 24px 8px rgba(31, 35, 41, 0.04), 0px 6px 12px 0px rgba(31, 35, 41, 0.04), 0px 4px 8px -8px rgba(31, 35, 41, 0.06);
        }
      }
      .@{popup-prefix}-body-main {
        display: flex;
        height: 100%;
        width: 100%;
        align-items: center;
        justify-content: center;
        p {
          color: var(~'@{tod-cssvars-prefix}-color-text-3');
        }
        .force-icon {
          font-size: 80px;
        }
      }
    }
  }

  &-footer {
    flex-shrink: 0;
    padding: 15px 0;
    height: 52px;
    display: flex;
    justify-content: center;
    border-top: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-8');
  }
  &-shrink-header {
    width: 100%;
    height: @shrinkHeaderHeight;
    position: absolute;
    top: 0;
    left: 0;
    background: transparent;
    pointer-events: none;
    .shrink-transition();
    &-cover {
      position: absolute;
      width: 100%;
      height: 100%;
      filter: blur(20px);
      opacity: 0.3;
      &-image {
        width: 100%;
        height: 100%;
        object-fit: cover;
        user-select: none;
      }
      &-mask {
        position: absolute;
        top: 0;
        width: 100%;
        height: 100%;
        background-image: linear-gradient(180deg, rgba(0, 0, 0, 0.16), rgba(0, 0, 0, 0.04));
      }
    }
  }
  &-top {
    position: absolute;
    top: 0;
    left: 0;
    display: flex;
    margin: 12px 16px 0;
    align-items: center;
    width: calc(100% - 32px);
    height: 32px;
    pointer-events: none;
    &-button {
      width: 24px;
      height: 24px;
      margin-right: 4px;
      font-size: 16px;
      border-radius: 50%;
      cursor: pointer;
      pointer-events: auto;
      text-align: center;
      color: var(~'@{tod-cssvars-prefix}-color-fill-5');

      &:hover {
        background-color: var(~'@{tod-cssvars-prefix}-color-bg-6');
      }
      svg {
        margin-right: 2px;
      }
    }
    &-center {
      // position: absolute;
      // left: 50%;
      // top: 50%;
      // transform: translate(-50%, -50%);
      justify-content: center;
      align-items: center;
      display: flex;
      opacity: 0;
      .shrink-transition();
      .@{tod-prefix}-user-profile-popup-top-avatar-container {
        position: relative;
        display: inline-block;
        width: 24px;
        height: 24px;
        border-radius: 50%;
        // background: @bg-body-overlay;
        margin-right: 6px;
      }
    }
    &-username {
      line-height: 20px;
      font-size: 14px;
      font-weight: 500;
      color: var(~'@{tod-cssvars-prefix}-color-text-1');
      max-width: 124px;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
  }
}
.@{tod-prefix}-user-profile-popup--shrink {
  .@{tod-prefix}-user-profile-popup-body-main-many-info {
    opacity: 0;
  }
  .@{tod-prefix}-user-profile-popup-shrink-header {
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-8');
    pointer-events: auto;
  }
  .@{tod-prefix}-user-profile-popup-top {
    &-center {
      opacity: 1;
    }
  }
}

.@{tod-prefix}-avatar-popover .@{arco-prefix}-avatar-group-popover {
  display: flex;
  flex-direction: column;
  .@{tod-prefix}-avatar-wrap {
    &:last-child {
      .user-profile-avatar {
        margin-bottom: 0;
      }
    }
  }
  .user-profile-avatar {
    margin-bottom: 4px;
    cursor: pointer;
  }
}

.@{tod-prefix}-user-profile-box {
  display: inline-block;
  cursor: pointer;
  .@{tod-prefix}-avatar-wrap {
    display: inline-block;
    cursor: pointer;
  }
  .rd-overflow-text {
    cursor: pointer;
  }
  .@{arco-prefix}-avatar-group-max-count-avatar {
    cursor: pointer;
  }
}

.@{tod-prefix}-user-profile__profile-section {
  position: relative;
  --profile-width: @profileWidth;
  --profile-length: 1;
  --profile-current-index: 0;

  width: var(--profile-width);
  overflow: hidden;
  border-radius: 8px;
  transform: translateZ(0); // 解决浏览器为Safari14时个人卡片圆角不显示问题
}

.@{tod-prefix}-user-profile__profiles-container--multi {
  display: flex;
  width: e('calc(var(--profile-width) * var(--profile-length))');
  transform: translateX(e('calc(-1 * var(--profile-current-index) * var(--profile-width))'));
  transition: transform 0.2s ease-out;
}
