@import '../../style/default.less';

.@{tod-prefix}-lark-group-select-item {
  display: flex;
  align-items: center;

  .avatar {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    margin-right: 6px;
    object-fit: cover;
  }

  .group-name {
    display: inline-block;
    overflow: hidden;
    text-overflow: ellipsis;
    overflow-wrap: break-word;
    white-space: nowrap;
    word-break: break-all;
    max-width: 100%;
    vertical-align: bottom;
  }
}

.@{tod-prefix}-lark-group-check-login {
  .intro-text {
    color: rgba(var(~'@{tod-cssvars-prefix}-gray-6'));
    margin: 0 6px 0 0;
  }

  .click-link {
    cursor: pointer;
  }
}
