@import '../../style/default.less';

@ve-o-prefix: @tod-prefix;
@bilayerPrefix: ~'@{ve-o-prefix}-bilayer';

@hoverBgColor: #f6f8fa;
@hoverColor: #1664ff;

.@{bilayerPrefix}-tab {
  * {
    margin: 0;
    padding: 0;
  }
  &.@{bilayerPrefix}-tab-wrapper {
    .@{arco-prefix}-tabs-header-title {
      height: 56px;
      align-items: flex-start;
      border-radius: 4px 4px 0 0;
    }
    .@{arco-prefix}-tabs-header-nav-card-gutter .@{arco-prefix}-tabs-header-title:hover {
      background-color: @hoverBgColor;
    }
    .@{arco-prefix}-tabs-header-title-text {
      margin-right: 6px;
    }
    .@{arco-prefix}-tabs-header {
      position: relative;
    }
    .@{arco-prefix}-tabs-header-nav-card-gutter.@{arco-prefix}-tabs-header-nav-horizontal::before {
      bottom: 0px;
    }
    .@{arco-prefix}-tabs-header-nav-card-gutter .@{arco-prefix}-tabs-header-title-active {
      // box-shadow: inset 0 2px 0 #006eff;
      border-top: none;
    }
    .@{arco-prefix}-tabs-header-nav-card-gutter
      .@{arco-prefix}-tabs-header-title-active.@{arco-prefix}-tabs-header-title {
      background-color: #fff;

      .@{bilayerPrefix}-tab-subtitle {
        font-weight: 400;
      }
    }
    .@{arco-prefix}-tabs-content.@{arco-prefix}-tabs-content-horizontal {
      border: none;
    }

    .@{arco-prefix}-tabs-header-nav-card-gutter .@{arco-prefix}-tabs-header-title {
      border-bottom: none;
    }
    .@{arco-prefix}-tabs-header-nav-card-gutter .@{arco-prefix}-tabs-header-title:first-of-type {
      margin-left: 32px;
    }
    .@{arco-prefix}-tabs-header-nav-card-gutter .@{arco-prefix}-tabs-add-icon {
      height: 56px;
    }
    .@{arco-prefix}-tabs-close-icon {
      font-size: 10px;
      margin-top: 2px;
      font-weight: 600;
    }
  }
  &-title:hover {
    color: @hoverColor;
  }
  &-subtitle {
    color: #80838a;
    font-size: 12px;
  }
  &-plus-icon-container {
    width: 20px;
    height: 20px;
    margin-left: 16px;
    line-height: 20px;
    border-radius: 100%;
    background-color: #f6f8fa;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
  }
}
