@import '../../style/default.less';

@stage-prefix-cls: ~'@{tod-prefix}-stage';

.@{stage-prefix-cls} {
  &-container {
    display: inline-block;
    box-sizing: border-box;
  }

  &-wrapper {
    display: flex;
    align-items: center;
  }

  &-stageWrapper {
    padding: 3px 3px;
    background: #fff;
    border-radius: 36px;
  }

  &-stageGap {
    display: flex;
    flex: 1 0 auto;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin: 0 -4px 0 -4px;
    background: #f2f3f5;
  }

  &-stageNode {
    position: relative;
    display: flex;
    align-items: center;
    height: 100%;
    padding: 4px 16px;
    line-height: 22px;
    white-space: nowrap;
    background: #fff;
    border: 1px solid #41464f00;
    border-radius: 30px;

    &:hover {
      .@{stage-prefix-cls}-name {
        color: #020814 !important;
      }
    }
  }

  &-innerGap {
    width: 1px;
    height: 12px;
    margin: 0 6px 0 8px;
  }

  &-name {
    font-weight: 500;
    font-size: 14px;
  }

  &-line {
    width: 1px;
    height: 10px;
    margin: 0 8px;
    background: #dde2e9;
  }

  &-detail {
    color: #41464f;
    font-size: 12px;
  }

  &-actionArea {
    margin-left: 8px;
  }

  &-time {
    font-size: 12px;
  }

  &-iconWrapper {
    display: flex;
    align-items: center;
    margin-right: 8px;
  }

  &-node {
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 8px 16px;
    font-weight: 500;
    font-size: 16px;
    border-radius: 20px;
  }

  &-running-animation {
    animation: Rotate 1000ms linear infinite;

    @keyframes Rotate {
      0% {
        transform: rotate(0deg);
      }

      50% {
        transform: rotate(180deg);
      }

      100% {
        transform: rotate(360deg);
      }
    }
  }
}
