@import '../../style/default.less';

// @arco-prefix: arco;

.@{tod-prefix}-list-wrapper {
  &.@{tod-prefix}-list-pagination-bordered {
    // border: 1px solid var(--color-border-2);
    border-radius: 4px;

    .@{tod-prefix}-list {
      // border-bottom: 1px solid var(--color-border-2);
      border-bottom-left-radius: 0;
      border-bottom-right-radius: 0;
    }

    .@{tod-prefix}-list-pagination {
      padding-bottom: 16px;
      padding-right: 8px;
      width: 100%;
      margin-top: 0;
      padding-top: 16px;
      justify-content: end;
      border-bottom-left-radius: 4px;
      border-bottom-right-radius: 4px;
      border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
      border-top: none;
    }
  }

  .@{tod-prefix}-list-card {
    .@{tod-prefix}-list-item {
      // FIXME: 间距，标题
      border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-2');
      border-radius: 4px;
      margin-bottom: 12px !important;

      &.@{arco-prefix}-list-item .@{arco-prefix}-list-item-main {
        box-shadow: none;
      }

      &:last-child {
        margin-bottom: 0;
      }
    }

    .@{arco-prefix}-list-header {
      font-size: 18px;
      padding-left: 0;
      border-bottom: none;
    }
  }

  .@{arco-prefix}-list-default .@{tod-prefix}-list-item-extra-content {
    padding: 12px 0;
  }
  .@{arco-prefix}-list-small .@{tod-prefix}-list-item-extra-content {
    padding: 8px 0;
  }
  .@{arco-prefix}-list-large .@{tod-prefix}-list-item-extra-content {
    padding: 16px 0;
  }

  .@{tod-prefix}-list.@{arco-prefix}-list-no-border .@{arco-prefix}-list-content .@{arco-prefix}-list-item:last-child {
    margin-bottom: 1px;
    .@{arco-prefix}-list-item-main {
      box-shadow: 0 1px 0 rgb(213 219 227 / 50%);
    }
  }

  // .@{tod-prefix}-list {
  // }
}
