@import '../../style/default.less';

.@{tod-prefix}-search-form {
  &.@{arco-prefix}-form-inline {
    flex-flow: row wrap;

    &.@{tod-prefix}-search-form-inline {
      flex-flow: row nowrap;
    }

    .@{arco-prefix}-form-layout-inline {
      margin-right: 12px;
    }

    .@{arco-prefix}-form-item {
      flex-shrink: 0;
    }
  }
}

.@{tod-prefix}-search-form-container.@{tod-prefix}-search-form-inline {
  display: flex;
  align-items: center;
}

.@{tod-prefix}-search-form-filter-dropdown {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px 20px 0 20px;
  background: var(~'@{tod-cssvars-prefix}-color-bg-1');
  box-shadow: 0 0 14px rgba(0, 0, 0, 0.1);
  border-radius: 4px;

  .@{arco-prefix}-form-item.@{arco-prefix}-form-layout-inline {
    margin: 0 0 20px 0;
  }
}

.@{tod-prefix}-search-form-filter-count {
  display: inline-block;
  padding: 0 6px;
  margin-left: 6px;
  min-width: 20px;
  color: @color-primary-7;
  background-color: rgba(var(~'@{tod-cssvars-prefix}-link-3'), 0.2);
  mix-blend-mode: normal;
  border-radius: 20px;
  font-weight: 400;
  font-size: 12px;
  line-height: 20px;
}

.@{tod-prefix}-search-form-reset {
  &.@{arco-prefix}-btn-size-default,
  & > button {
    padding: 0 8px;
  }
}

.@{tod-prefix}-search-form-filter {
  &.@{arco-prefix}-btn-size-default,
  & > button {
    padding: 0 10px;
  }
}
