@import '../../style/default.less';
@ve-o-prefix: @tod-prefix;
@guidePrefix: ~'@{ve-o-prefix}-guide';

.@{guidePrefix}-richcard {
  position: absolute;
  width: 320px;
  padding: 16px;
  z-index: 1100;
  background: var(~'@{tod-cssvars-prefix}-color-white');
  border-radius: 8px;
  box-sizing: border-box;
  box-shadow: 0px 5px 15px 0px rgba(0, 0, 0, 0.05), 0px 15px 35px -2px rgba(0, 0, 0, 0.05);

  & * {
    text-align: left;
  }

  &-image-title {
    margin-top: -16px;
    margin-left: -16px;
    width: calc(100% + 32px);
    margin-bottom: 6px;

    image,
    img {
      width: 100%;
    }
  }

  &-title {
    display: block;
    width: calc(100% - 12px);
    font-weight: 500;
    font-size: 16px;
    height: 24px;
    color: var(~'@{tod-cssvars-prefix}-color-text-1');
    line-height: 24px;
    margin-bottom: 8px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &-content {
    font-size: 12px;
    line-height: 22px;
    font-weight: 400;
    color: var(~'@{tod-cssvars-prefix}-color-text-2');
    margin-bottom: 16px;
  }

  &-close-icon {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 24px;
    height: 24px;
    font-size: 24px;
    text-align: center;
    line-height: 24px;
    cursor: pointer;

    &:hover {
      background: rgba(2, 8, 20, 0.05);
      border-radius: 4px;
    }
  }

  &-arrow {
    position: absolute;
    width: 8px;
    height: 8px;
    background: linear-gradient(106.19deg, #f0f5ff -29.01%, #f8faff 68.62%);
    transform: rotate(45deg);
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-3');
    border-radius: 1px;
  }

  &-footer {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;

    & * {
      font-size: 12px;
      font-weight: 400;
    }

    &-text {
      color: var(~'@{tod-cssvars-prefix}-color-text-3');
      font-weight: 500;
    }

    &-btn-group {
      display: flex;
      justify-self: flex-end;
    }

    &-prev-btn {
      margin-right: 8px;
    }
  }
}

