.@{guidePrefix}-tip {
  position: absolute;
  width: 272px;
  padding: 12px;
  z-index: 1100;
  background: rgb(var(~'@{tod-cssvars-prefix}-primary-5'));
  border-radius: 8px;
  box-sizing: border-box;

  &.bits-light {
    border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-3');
    background: linear-gradient(219deg, #6332ff 0%, #00e5e5 45.87%, #1664ff 100%);
    box-shadow: 0px 10px 20px 0px rgba(0, 0, 0, 0.05);
    background-size: calc(100% + 14.14px) calc(100% + 14.14px);
    background-position: -7.06px -7.06px;
    border-radius: 12px;
    padding: 0;

    .@{guidePrefix}-tip-content-wrap {
      margin: 1px;
      border-radius: 10px;
      padding: 11px 14px 14px 14px;
      background: var(~'@{tod-cssvars-prefix}-color-white');
    }

    .@{guidePrefix}-tip-arrow {
      background: var(~'@{tod-cssvars-prefix}-color-white');
      border: 1px solid var(~'@{tod-cssvars-prefix}-color-border-3');
      border-radius: 1px;
      box-shadow: 0px 10px 20px 0px rgba(0, 0, 0, 0.05);
    }

    .@{guidePrefix}-tip-arrow-gradient {
      width: 14.14px;
      height: 14.14px;

      position: absolute;
      background: linear-gradient(219deg, #6332ff 0%, #00e5e5 45.87%, #1664ff 100%);
      z-index: 9;
    }

    .@{guidePrefix}-title {
      color: var(~'@{tod-cssvars-prefix}-color-text-1');
    }

    .@{guidePrefix}-content {
      color: var(~'@{tod-cssvars-prefix}-color-text-2');
    }

    .@{guidePrefix}-tip-close-icon {
      color: var(~'@{tod-cssvars-prefix}-color-fill-4');
    }
  }

  & * {
    text-align: left;
  }

  &-title {
    display: block;
    width: calc(100% - 14px);
    font-weight: 500;
    font-size: 14px;
    height: 22px;
    color: var(~'@{tod-cssvars-prefix}-color-white');
    line-height: 22px;
    margin-bottom: 6px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &-content {
    width: calc(100% - 12px);
  }

  &-title + &-content {
    width: 100%;
  }

  &-content {
    font-size: 12px;
    line-height: 22px;
    font-weight: 400;
    color: var(~'@{tod-cssvars-prefix}-color-white');
  }

  &-close-icon {
    position: absolute;
    top: 12px;
    right: 12px;
    width: 24px;
    height: 24px;
    font-size: 24px;
    color: var(~'@{tod-cssvars-prefix}-color-white');
    text-align: center;
    line-height: 24px;
    cursor: pointer;

    &:hover {
      background: rgba(255, 255, 255, 0.2);
      border-radius: 4px;
    }
  }

  &-arrow {
    position: absolute;
    width: 10px;
    height: 10px;
    background: rgb(var(~'@{tod-cssvars-prefix}-primary-5'));
    transform: rotate(45deg);
    border-radius: 1px;
  }

  &-footer {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 12px;

    & * {
      font-size: 12px;
      font-weight: 400;
    }

    &-text {
      color: var(~'@{tod-cssvars-prefix}-color-white');
      font-weight: 500;
    }

    &-btn-group {
      display: flex;
      justify-self: flex-end;
    }

    &-prev-btn {
      margin-right: 8px;
      border-color: transparent !important;
      color: var(~'@{tod-cssvars-prefix}-color-white') !important;
      box-shadow: none !important;
      &:hover {
        background: rgba(255, 255, 255, 0.1) !important;
        border-color: transparent !important;
      }
    }

    &-next-btn {
      background: var(~'@{tod-cssvars-prefix}-color-white') !important;
      border-color: var(~'@{tod-cssvars-prefix}-color-white') !important;
      color: var(~'@{tod-cssvars-prefix}-color-fill-4') !important;

      &:hover {
        background: rgba(255, 255, 255, 0.9) !important;
        border-color: rgba(255, 255, 255, 0.9) !important;
      }
    }
  }
}

.@{guidePrefix}-hotspot {
  position: absolute;
  width: 20px;
  height: 20px;

  &-outer {
    width: 20px;
    height: 20px;
    animation: scale 1.4s infinite linear;
    background: rgba(106, 166, 255, 0.6);
    border-radius: 50%;
  }

  &-inner {
    position: absolute;
    left: 0;
    top: 0;
    right: 0;
    bottom: 0;
    margin: auto;
    width: 12px;
    height: 12px;
    -webkit-border-radius: 50%;
    border-radius: 50%;
    background-color: rgb(var(~'@{tod-cssvars-prefix}-primary-5'));
  }

  @keyframes scale {
    0% {
      transform: scale(1.3);
    }

    50% {
      transform: scale(1);
    }

    100% {
      transform: scale(1.3);
    }
  }
}
