@import '../../../style/default.less';
@import './token.less';

.@{vod-prefix}-card-pro {
  position: relative;
  border: 1px solid @card-color-border;
  background-color: @card-default-bg;
  border-radius: 4px;
  padding: 16px;
  width: 320px;
  overflow: hidden;

  &-isHoverable {
    &:hover {
      box-shadow: 0 15px 35px -2px rgba(0, 0, 0, 0.05), 0 5px 15px rgba(0, 0, 0, 0.03);
    }
  }

  &-isTab {
    border-radius: @card-tab-radius;

    &:hover {
      box-shadow: 0 15px 35px -2px rgba(0, 0, 0, 0.05), 0 5px 15px rgba(0, 0, 0, 0.03);
    }
  }

  &-checkable {
    &:hover {
      box-shadow: 0 15px 35px -2px rgba(0, 0, 0, 0.05), 0 5px 15px rgba(0, 0, 0, 0.03);
    }
  }

  &-isTab-active {
    box-shadow: @card-tab-outline-shadow;

    &::before {
      content: ' ';
      position: absolute;
      background-color: @card-color-tab-active;
      width: 4px;
      height: 100%;
      top: 0;
      left: 0;
      border-radius: @card-tab-radius 0 0 @card-tab-radius;
    }
  }

  &-isChecked {
    border: 1px solid @card-color-check-active;

    &::after {
      content: '';
      position: absolute;
      background-image: url('data:image/png;base64,');
      background-size: cover;
      width: 24px;
      height: 24px;
      top: -1px;
      right: -1px;
    }
  }

  &__content-wrapper {
    width: 100%;
    display: flex;
  }

  &__cover-wrapper {
    width: 100%;
  }

  &__footer {
    width: 100%;
  }

  &-title {
    font-weight: 500;
    font-size: 14px;
    line-height: 22px;
    color: @card-color-title;
  }

  &-content {
    margin-top: 2px;
    font-size: 12px;
    line-height: 20px;
    color: @card-color-content;
  }

  &-avatar {
    margin-right: 12px;
  }
}
