@import '@cloud-ui-react/common-lib/es/style/vars.less';
@import '../../../style/default.less';
@import '../CloudStar/style/index.less';

.@{tod-prefix}-byte-tree-selector {
  mark {
    background-color: transparent;
  }
  &-tip {
    .icon {
      color: rgb(var(~'@{tod-cssvars-prefix}-arcoblue-6'));
      padding-right: 4px;
      font-size: 18px;
      padding-top: 5px;
    }
    color: rgb(var(~'@{tod-cssvars-prefix}-gray-8'));
    background: rgb(var(~'@{tod-cssvars-prefix}-link-1'));
    position: absolute;
    top: 0;
    z-index: 10000;
    left: 0;
    right: 0;
    padding: 4px 10px;
  }
}

.@{tod-prefix}-byte-tree-selector-tree > div > div {
  overflow-x: auto;
}

.@{tod-prefix}-byte-tree-selector-tree{

  .@{prefix}-tree-node-title:hover {
    background-color: var(~'@{tod-cssvars-prefix}-color-bg-4');
  }
  .@{prefix}-tree-node {
    // width: max-content;
    .@{prefix}-tree-node-title-text {
      width: max-content;
      display: block;
      & .@{tod-prefix}-byte-tree-selector-node {
        .high-light-node {
          color: rgb(var(~'@{tod-cssvars-prefix}-gray-6'));;
          .divider {
            display: inline-block;
            width: 2px;
            margin: 0 4px;
            color: rgb(var(~'@{tod-cssvars-prefix}-gray-4'));;
            font-weight: bolder;
          }
          & XByteTreeSelectorMark {
            background-color: yellow;
            color: rgb(var(~'@{tod-cssvars-prefix}-gray-10'));
            font-weight: 500;
          }
        }
      }
    }
  }

  .@{prefix}-tree-node {
    align-items: center;
    .flavor-extra{
      margin-right: 12px;
    }
    .star {
      opacity: 0;
      pointer-events: none;
    }

    &:hover .star {
      opacity: 1;
      pointer-events: initial;
    }
  }

}


.@{tod-prefix}-byte-tree-selector-tabs {
  .arco-tabs-header {
    padding-left: 12px;
  }
}

.@{tod-prefix}-byte-tree-selector-listSelect{
  .@{prefix}-menu .@{prefix}-menu-item .@{prefix}-icon{
    margin-right: 0;
  }
  .list-select-item{
    .extra-node-hover-display {
      opacity: 0;
      pointer-events: none;
    }
    &:hover {
     .extra-node-hover-display {
        opacity: 1;
        pointer-events: initial;
      }
    }
  }

}