@import '../../style/default.less';

.@{tod-prefix}-action-list{
  padding: 12px 16px 0;
  background:  linear-gradient(160deg, rgb(var(~'@{arco-cssvars-prefix}-primary-2')),hsla(0,0%,100%,0) 60px),#fff;
  .@{arco-prefix}-list-header{
    padding: 0 !important;
    border: none;
  }
  .@{tod-prefix}-action-list-content{
    .@{tod-prefix}-action-list-item:last-child{
      border: none;
    }
  }
}

.@{tod-prefix}-action-list-header{
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
  font-style: normal;
  font-weight: 500;
  line-height: 22px;
  margin-bottom: 4px;
  .@{tod-prefix}-action-list-header-title{
    display: flex;
    gap: 6px;
    align-items: center;
  }
}

.@{tod-prefix}-action-list-item{
  display: flex;
  padding: 12px 0;
  border-bottom: 1px solid var(~'@{arco-cssvars-prefix}-color-border-2', #EAEDF1);;
  .@{tod-prefix}-action-list-item-content{
    flex: 1;
    display: inline-flex;
    flex-direction: column;
    gap: 2px;
    .@{tod-prefix}-action-list-item-content-title{
      font-size: 14px;
      font-style: normal;
      font-weight: 500;
      line-height: 22px; 
    }
    .@{tod-prefix}-action-list-item-content-description{
      color: var(~'@{arco-cssvars-prefix}-color-text-3', '#737A87');
      font-size: 12px;
      font-style: normal;
      font-weight: 400;
      line-height: 20px; 
    }
  }
  .@{tod-prefix}-action-list-item-action{
    display: inline-flex;
    align-items: center;
  }
}

.@{tod-prefix}-action-list-footer{
  cursor: pointer;
  padding: 10px 0;
}

.@{tod-prefix}-action-list-footer-inner{
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 20px;
  color: var(~'@{tod-cssvars-prefix}-color-text-2', '#42464E');
  .@{tod-prefix}-action-list-footer-inner-icon{
    display: inline-block;
    width: 12px;
    height: 12px;
    font-size: 12px;
  }
}