@import '../../style/default.less';

.@{tod-prefix}-tree .@{tod-prefix}-tree-tag {
  height: 16px;
  margin-right: 6px;
  padding: 0 6px;
  color: var(~'@{tod-cssvars-prefix}-color-text-2');
  font-size: 12px;
  border-radius: 4px;
  background-color: var(~'@{tod-cssvars-prefix}-color-bg-4');
}

.@{tod-prefix}-tree .@{tod-prefix}-tree-tag-after {
  margin-right: 0px;
  margin-left: 6px;
}

.@{tod-prefix}-tree.@{arco-prefix}-tree-size-mini .@{tod-prefix}-tree-tag {
  margin-right: 2px;
  transform: scale(0.83);
}

.@{tod-prefix}-tree.@{arco-prefix}-tree-size-mini .@{tod-prefix}-tree-tag-after {
  margin-left: 2px;
  transform: scale(0.83);
}

.@{tod-prefix}-tree .@{tod-prefix}-tree-tag-wrap-right {
  margin-left: 6px;
}

.@{tod-prefix}-tree .@{tod-prefix}-tree-tag-wrap-left {
  margin-right: 6px;
}

.@{tod-prefix}-tree.@{arco-prefix}-tree-size-mini .@{tod-prefix}-tree-tag-wrap-left {
  margin-right: 2px;
}

.@{tod-prefix}-tree.@{arco-prefix}-tree-size-mini .@{tod-prefix}-tree-tag-wrap-right {
  margin-left: 2px;
}

.@{tod-prefix}-tree-label {
  display: inline-flex;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  align-items: center;
  justify-content: center;
  // @gray-8
  color: rgb(var(~'@{tod-cssvars-prefix}-gray-8'));
  // @gray-2
  background-color: rgb(var(~'@{tod-cssvars-prefix}-gray-2'));
  margin-left: 8px;
  font-size: 12px;
}

.@{tod-prefix}-tree-more {
  position: absolute;
  display: inline-flex;
  align-items: center;
  right: 8px;
  top: 0;
  height: 100%;
}

.@{tod-prefix}-tree-actions {
  display: flex;
  opacity: 0;
}

.@{arco-prefix}-tree-node:hover .@{tod-prefix}-tree-actions {
  opacity: 1;
}

.@{arco-prefix}-tree-node-selected .@{tod-prefix}-tree-actions {
  opacity: 1;
}

.@{tod-prefix}-tree-action-item {
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 4px;
}

.@{tod-prefix}-tree-diff {
  font-size: 12px;
}

.@{tod-prefix}-tree-diff-addition {
  margin-left: 4px;
  // @success-6
  color: rgb(var(~'@{tod-cssvars-prefix}-success-6'));
}

.@{tod-prefix}-tree-diff-deletion {
  margin-left: 4px;
  // @danger-6
  color: rgb(var(~'@{tod-cssvars-prefix}-danger-6'));
}

.@{tod-prefix}-tree .@{tod-prefix}-tree-icon {
  stroke: none;
}


.@{tod-prefix}-tree-directory-icon-content {
  // @color-text-2
  fill: var(~'@{tod-cssvars-prefix}-color-text-2');
}

.@{arco-prefix}-tree-node-expanded .@{tod-prefix}-tree-directory-icon-content {
  // @color-text-3
  fill: var(~'@{tod-cssvars-prefix}-color-text-3');
}

.@{arco-prefix}-tree-node-selected .@{tod-prefix}-tree-directory-icon-content {
  // @primary-7
  fill: rgb(var(~'@{tod-cssvars-prefix}-primary-7'));
}

.@{tod-prefix}-tree-file-icon-content {
  fill: var(~'@{tod-cssvars-prefix}-color-text-3');
  stroke: var(~'@{tod-cssvars-prefix}-color-text-3');
}

.@{arco-prefix}-tree-node-selected .@{tod-prefix}-tree-file-icon-content {
  fill: rgb(var(~'@{tod-cssvars-prefix}-primary-7'));
  stroke: rgb(var(~'@{tod-cssvars-prefix}-primary-7'));
}
