@import '../../../style/default.less';

@ve-o-prefix: @tod-prefix;

.avatar-common-style {
  flex-shrink: 0;
  align-items: center;
  flex-wrap: nowrap;
}
.@{ve-o-prefix}-base-avatar,
.@{tod-prefix}-avatar {
  display: flex;
  .avatar-common-style;
  .@{ve-o-prefix}-pure-avatar {
    display: flex;
    .avatar-common-style;
  }
  &-group {
    .avatar-common-style;
    &.@{arco-prefix}-volc3-avatar-group,
    &.@{arco-prefix}-avatar-group {
      display: flex;
    }
    &-popover {
      .@{arco-prefix}-volc3-avatar-group-popover > .@{ve-o-prefix}-avatar,
      .@{arco-prefix}-avatar-group-popover > .@{ve-o-prefix}-avatar {
        margin-bottom: 4px;
      }
      .@{arco-prefix}-volc3-avatar-group-popover > .@{ve-o-prefix}-avatar-department,
      .@{arco-prefix}-avatar-group-popover > .@{ve-o-prefix}-avatar-department {
        display: block;
        margin-bottom: 4px;
      }
    }
    &-mix {
      display: flex;
      align-items: center;
      .@{ve-o-prefix}-avatar-group > .@{ve-o-prefix}-avatar:last-of-type {
        .rd-overflow-text {
          display: none;
        }
      }
      &-fake {
        margin-left: 4px;
        .@{ve-o-prefix}-avatar {
          display: none;
        }
      }
    }
  }
  &-department {
    display: inline-block;
    padding: 1px 6px 1px 1px;
    border: 1px solid #eaedf1;
    border-radius: 30px;
  }
  .rd-overflow-text-desc {
    color: var(~'@{tod-cssvars-prefix}-color-fill-2');
  }
}
.@{ve-o-prefix}-base-avatar .@{ve-o-prefix}-pure-avatar {
  .@{arco-prefix}-avatar-text {
    color: var(~'@{tod-cssvars-prefix}-color-white');
    text-align: center;
    vertical-align: middle;
    white-space: pre;
  }
}
