@import '../../style/default.less';

.@{ve-o-design-prefix}-input-search-button {
  &.@{arco-prefix}-input-group-wrapper {
    position: relative;
    .@{arco-prefix}-input-group {
      .@{arco-prefix}-input-inner-wrapper {
        border: 1px solid var(~'@{arco-cssvars-prefix}-color-border-3');
        border-radius: var(--border-radius-medium);
        &:hover {
          border-color: rgb(var(~'@{arco-cssvars-prefix}-link-6'));
        }
      }
      .@{arco-prefix}-input-inner-wrapper-error {
        border: 1px solid var(~'@{arco-cssvars-prefix}-color-alpha-danger3');
        border-radius: var(--border-radius-medium);
        &:hover {
          border-color: rgb(var(~'@{arco-cssvars-prefix}-danger-6'));
        }
      }
      .@{arco-prefix}-input-inner-wrapper-focus.@{arco-prefix}-input-inner-wrapper-error {
        border-color: rgb(var(~'@{arco-cssvars-prefix}-danger-6'));
      }

      &-addafter {
        position: absolute;
        right: 28px;
        top: 4px;
        z-index: 1;
        width: 0;
        .@{arco-prefix}-btn.@{arco-prefix}-btn-primary {
          width: 24px;
          height: 24px;
          padding: 0;
          border-radius: var(--border-radius-small);
          .force-icon {
            font-size: 12px;
            vertical-align: -2px;
          }
        }
      }
    }
  }
  &.@{arco-prefix}-input-group-wrapper-small {
    .@{arco-prefix}-input-group {
      &-addafter {
        right: 26px;
        top: 2px;
      }
    }
  }
  &.@{arco-prefix}-input-group-wrapper-large {
    .@{arco-prefix}-input-group {
      &-addafter {
        right: 28px;
        top: 5px;
      }
    }
  }
  &.@{arco-prefix}-input-group-wrapper-disabled {
    .@{arco-prefix}-input-group {
      .@{arco-prefix}-input-inner-wrapper {
        &:hover {
          border-color: var(~'@{arco-cssvars-prefix}-color-border-3');
        }
      }
    }
  }
}
